(window.__ixData=window.__ixData||[]).push(function(D){D["mvc-partials"]=[{t:"sb",ti:"Lab Step Builder: Computing First & Mixed Partial Derivatives",ti_ar:"بناء خطوات المعمل: حساب المشتقات الجزئية الأولى والمختلطة",steps:[{l:"For \\(f(x,y) = x^3 y^2 - 4xy + 5y\\), find \\(f_x(x,y) = 3x^2 y^2 -\\)",a:"4y",h:"d/dx(-4xy) with y treated as constant is -4y"},{l:"Find \\(f_{xy}(x,y) = \\dfrac{\\partial}{\\partial y}(3x^2 y^2 - 4y) = 6x^2 y -\\)",a:"4",h:"d/dy(-4y) = -4"},{l:"By Clairaut's theorem, does \\(f_{yx} = f_{xy}\\) for this smooth polynomial? (yes/no):",a:"yes",h:"Mixed partials are equal when second derivatives are continuous."}],steps_ar:[{l:"للدالة \\(f(x,y) = x^3 y^2 - 4xy + 5y\\)، أوجد \\(f_x(x,y) = 3x^2 y^2 -\\)",a:"4y",h:"مشتقة -4xy بالنسبة إلى x مع معاملة y كثابت هي -4y"},{l:"أوجد \\(f_{xy}(x,y) = \\dfrac{\\partial}{\\partial y}(3x^2 y^2 - 4y) = 6x^2 y -\\)",a:"4",h:"d/dy(-4y) = -4"},{l:"وفقاً لمبرهنة كليرو، هل \\(f_{yx} = f_{xy}\\) لكثيرة الحدود الملساء هذه؟ (yes/no):",a:"yes",h:"المشتقات الجزئية المختلطة متساوية عندما تكون المشتقات من الرتبة الثانية مستمرة."}]},{t:"qc",ti:"Lab Check: Tangent Plane to a Surface",ti_ar:"فحص المعمل: المستوى المماس لسطح",q:"Find the normal vector \\(\\mathbf{n}\\) to the tangent plane of \\(z = f(x,y)\\) at \\((x_0, y_0)\\):",q_ar:"أوجد المتجه العمودي \\(\\mathbf{n}\\) على المستوى المماس للسطح \\(z = f(x,y)\\) عند النقطة \\((x_0, y_0)\\):",o:["\\(\\langle f_x, f_y, -1 \\rangle\\)","\\(\\langle f_x, f_y, 1 \\rangle\\)","\\(\\langle 1, 1, f_z \\rangle\\)","\\(\\langle -f_y, f_x, 0 \\rangle\\)"],o_ar:["\\(\\langle f_x, f_y, -1 \\rangle\\)","\\(\\langle f_x, f_y, 1 \\rangle\\)","\\(\\langle 1, 1, f_z \\rangle\\)","\\(\\langle -f_y, f_x, 0 \\rangle\\)"],a:0,ex:"Rearranging \\(z = f(x,y)\\) into \\(F(x,y,z) = f(x,y) - z = 0\\), the gradient \\(\\nabla F = \\langle f_x, f_y, -1 \\rangle\\) gives the normal vector.",ex_ar:"بإعادة كتابة \\(z = f(x,y)\\) في الصورة \\(F(x,y,z) = f(x,y) - z = 0\\)، يعطي متجه التدرج \\(\\nabla F = \\langle f_x, f_y, -1 \\rangle\\) المتجه العمودي المطلوب."},{t:"num",ti:"Evaluate Mixed Second Partial Derivative",ti_ar:"حساب المشتقة الجزئية المختلطة من الرتبة الثانية",q:"Given \\(f(x, y) = 2x^2 y^3 - 5xy + 4x - 6y\\), evaluate the mixed second partial derivative \\(f_{xy}(1, 2)\\):",q_ar:"إذا كانت \\(f(x, y) = 2x^2 y^3 - 5xy + 4x - 6y\\)، فاحسب قيمة المشتقة الجزئية المختلطة \\(f_{xy}(1, 2)\\):",a:43,tol:.001,h:"f_x = 4x y³ - 5y + 4. Then differentiate with respect to y: f_xy = 12x y² - 5. Evaluate at (1, 2).",h_ar:"f_x = 4x y³ - 5y + 4. ثم اشتق بالنسبة إلى y: f_xy = 12x y² - 5. احسب القيمة عند (1, 2).",sol:"f_xy = 12x y² - 5. At (1, 2): 12(1)(4) - 5 = 48 - 5 = 43.",sol_ar:"f_xy = 12x y² - 5. عند (1, 2): 12(1)(4) - 5 = 48 - 5 = 43."},{t:"ord",ti:"Order the Steps: Tangent Plane to z = f(x, y)",ti_ar:"ترتيب الخطوات: معادلة المستوى المماس لـ z = f(x, y)",q:"Order the steps to construct the tangent plane equation to z = f(x, y) at the point (x₀, y₀, z₀):",q_ar:"رتّب خطوات إنشاء معادلة المستوى المماس للسطح z = f(x, y) عند النقطة (x₀, y₀, z₀):",items:["Compute the first-order partial derivatives f_x(x, y) and f_y(x, y)","Evaluate f_x(x₀, y₀) and f_y(x₀, y₀) at the point of tangency","Verify or compute z₀ = f(x₀, y₀) if not given explicitly","Substitute into the formula: z - z₀ = f_x(x₀, y₀)(x - x₀) + f_y(x₀, y₀)(y - y₀)","Expand and rearrange into the standard form Ax + By + Cz = D"],items_ar:["حساب المشتقات الجزئية الأولى f_x(x, y) و f_y(x, y)","تعويض النقطة لحساب f_x(x₀, y₀) و f_y(x₀, y₀) عند نقطة التماس","التحقق من قيمة z₀ = f(x₀, y₀) أو حسابها إذا لم تكن معطاة صراحة","التعويض في الصيغة: z - z₀ = f_x(x₀, y₀)(x - x₀) + f_y(x₀, y₀)(y - y₀)","فك الأقواس وإعادة الترتيب إلى الصورة القياسية Ax + By + Cz = D"],sol:"The tangent plane utilizes evaluated partial derivatives as slopes along coordinate directions.",sol_ar:"يستخدم المستوى المماس المشتقات الجزئية المحسوبة كأميال على طول اتجاهات المحاور الإحداثية."},{t:"cat",ti:"Classify Partial Derivatives: Holding x vs. Holding y Constant",ti_ar:"تصنيف المشتقات الجزئية: تثبيت x مقابل تثبيت y",categories:["Computed Holding y Constant (∂/∂x)","Computed Holding x Constant (∂/∂y)"],categories_ar:["محسوبة مع تثبيت y كـثابت (∂/∂x)","محسوبة مع تثبيت x كـثابت (∂/∂y)"],items:[{s:"f_x(x, y) measuring slope along coordinate slice y = constant",cat:0},{s:"f_y(x, y) measuring slope along coordinate slice x = constant",cat:1},{s:"Differentiating x² y³ to obtain 2x y³",cat:0},{s:"Differentiating x² y³ to obtain 3x² y²",cat:1},{s:"Rate of change in the direction of unit vector i = ⟨1, 0⟩",cat:0}],items_ar:[{s:"f_x(x, y) لقياس الميل على طول الشريحة الإحداثية y = ثابت",cat:0},{s:"f_y(x, y) لقياس الميل على طول الشريحة الإحداثية x = ثابت",cat:1},{s:"اشتقاق x² y³ للحصول على 2x y³",cat:0},{s:"اشتقاق x² y³ للحصول على 3x² y²",cat:1},{s:"معدل التغير في اتجاه متجه الوحدة i = ⟨1, 0⟩",cat:0}],sol:"∂/∂x treats y as a constant multiplier; ∂/∂y treats x as a constant multiplier.",sol_ar:"يعامل التفاضل الجزئي ∂/∂x المتغير y كثابت؛ بينما يعامل التفاضل الجزئي ∂/∂y المتغير x كثابت."},{t:"se",ti:"Spot the Error: Partial Differentiation Treating the Other Variable as Constant",ti_ar:"اكتشف الخطأ: الاشتقاق الجزئي بتثبيت المتغير الآخر",q:"A student computes \\(f_x(x, y)\\) for \\(f(x, y) = x^2 y^3 + \\sin(y)\\). Which step contains an error?",q_ar:"يحسب طالب المشتقة الجزئية \\(f_x(x, y)\\) للدالة \\(f(x, y) = x^2 y^3 + \\sin(y)\\). أي خطوة تتضمن خطأ؟",steps:["Hold \\(y\\) constant while differentiating with respect to \\(x\\).","Differentiate \\(x^2 y^3\\) wrt \\(x\\) to obtain \\(2x y^3\\).","Differentiate \\(\\sin(y)\\) wrt \\(x\\) to obtain \\(\\cos(y)\\).","Write \\(f_x(x, y) = 2x y^3 + \\cos(y)\\)."],steps_ar:["تثبيت المتغير \\(y\\) كثابت أثناء الاشتقاق بالنسبة لـ \\(x\\).","اشتقاق \\(x^2 y^3\\) بالنسبة لـ \\(x\\) للحصول على \\(2x y^3\\).","اشتقاق \\(\\sin(y)\\) بالنسبة لـ \\(x\\) وكتابته \\(\\cos(y)\\).","كتابة الناتج \\(f_x(x, y) = 2x y^3 + \\cos(y)\\)."],errorStep:3,reasons:["When \\(y\\) is held constant, \\(\\sin(y)\\) is a pure constant with respect to \\(x\\), so \\(\\frac{\\partial}{\\partial x}[\\sin(y)] = 0\\) and \\(f_x = 2xy^3\\).","\\(x^2 y^3\\) requires the product rule giving \\(2xy^3 + 3x^2y^2\\).","\\(\\frac{\\partial}{\\partial x}[\\sin(y)] = -\\cos(y)\\)."],reasons_ar:["عند تثبيت \\(y\\) تكون \\(\\sin(y)\\) ثابتاً بالنسبة لـ \\(x\\)، لذا مشتقتها الجزئية تساوي \\(0\\) ويكون \\(f_x = 2xy^3\\).","اشتقاق \\(x^2 y^3\\) يتطلب قاعدة الضرب.","مشتقة \\(\\sin(y)\\) بالنسبة لـ \\(x\\) تساوي \\(-\\cos(y)\\)."],correctReason:0},{t:"ms",ti:"Examiner Mode: Gradient Vector & Hessian Classification (Functions of Several Variables, Limits, Partial Derivatives & Differentiability)",ti_ar:"وضع المصحح: متجه التدرج ومصفوفة هيس (الدوال متعددة المتغيرات والنهايات والمشتقات الجزئية وقابلية الاشتقاق)",q:"Let \\(f(x, y) = 4x^2 + 4xy + y^2\\). (a) Compute \\(\\nabla f(1, 2)\\). (b) Compute the Hessian determinant \\(D = f_{xx}f_{yy} - (f_{xy})^2\\).",q_ar:"لتكن \\(f(x, y) = 4x^2 + 4xy + y^2\\). (أ) احسب متجه التدرج \\(\\nabla f(1, 2)\\). (ب) احسب محدد هيس \\(D = f_{xx}f_{yy} - (f_{xy})^2\\).",parts:[{label:"Part (a) — Partial Derivatives & Gradient",marks:2,rubric:[{code:"M1",marks:1,text:"\\(f_x = 8x + 4y,\\quad f_y = 4x + 2y\\)."},{code:"A1",marks:1,text:"At \\((1, 2)\\): \\(\\nabla f(1, 2) = \\langle 16, 8 \\rangle\\)."}]},{label:"Part (b) — Second-Derivative Discriminant",marks:2,rubric:[{code:"M1",marks:1,text:"\\(f_{xx} = 8,\\; f_{yy} = 2,\\; f_{xy} = 4\\)."},{code:"A1",marks:1,text:"\\(D = (8)(2) - 4^2 = 0\\)."}]}],parts_ar:[{label:"الجزء (أ) — المشتقات الجزئية ومتجه التدرج",marks:2,rubric:[{code:"M1",marks:1,text:"\\(f_x = 8x + 4y,\\quad f_y = 4x + 2y\\)."},{code:"A1",marks:1,text:"عند \\((1, 2)\\): \\(\\nabla f(1, 2) = \\langle 16, 8 \\rangle\\)."}]},{label:"الجزء (ب) — محدد المشتقات الجزئية الثانية (هيس)",marks:2,rubric:[{code:"M1",marks:1,text:"\\(f_{xx} = 8,\\; f_{yy} = 2,\\; f_{xy} = 4\\)."},{code:"A1",marks:1,text:"\\(D = 0\\)."}]}]},{t:"mt",ti:"Matching: Partial Derivatives, Tangent Planes & Gradient Geometry",ti_ar:"مطابقة: المشتقات الجزئية والمستوى المماس وهندسة التدرج",p:[{l:"Gradient vector \\(\\nabla f(x, y)\\)",r:"\\(\\langle f_x(x, y),\\; f_y(x, y) \\rangle\\), orthogonal to level curves"},{l:"Tangent plane to \\(z = f(x, y)\\) at \\((a, b)\\)",r:"\\(z = f(a,b) + f_x(a,b)(x - a) + f_y(a,b)(y - b)\\)"},{l:"Clairaut’s theorem for \\(C^2\\) functions",r:"Mixed partials commute: \\(f_{xy} = f_{yx}\\)"},{l:"Directional derivative \\(D_{\\mathbf{u}} f\\) (unit \\(\\mathbf{u}\\))",r:"\\(\\nabla f \\cdot \\mathbf{u} = \\|\\nabla f\\|\\cos\\theta\\)"}],p_ar:[{l:"متجه التدرج \\(\\nabla f(x, y)\\)",r:"\\(\\langle f_x, f_y \\rangle\\) عمودي على منحنيات المستوى"},{l:"المستوى المماس للسطح \\(z = f(x, y)\\)",r:"\\(z = f(a,b) + f_x(a,b)(x - a) + f_y(a,b)(y - b)\\)"},{l:"مبرهنة كليرو للدوال المتصلة \\(C^2\\)",r:"تساوي المشتقات المختلطة \\(f_{xy} = f_{yx}\\)"},{l:"المشتقة الاتجاهية \\(D_{\\mathbf{u}} f\\)",r:"\\(\\nabla f \\cdot \\mathbf{u} = \\|\\nabla f\\|\\cos\\theta\\)"}]},{t:"qc",ti:"Quick Check: Clairaut’s Mixed Partial Symmetry",ti_ar:"فحص سريع: تماثل المشتقات الجزئية المختلطة (كليرو)",q:"If \\(f(x, y)\\) has continuous second-order partial derivatives on \\(\\mathbb{R}^2\\) and \\(f_{xy}(1, 2) = -7\\), what is \\(f_{yx}(1, 2)\\)?",q_ar:"إذا كانت للدالة \\(f(x, y)\\) مشتقات جزئية ثانية متصلة وكان \\(f_{xy}(1, 2) = -7\\)، فما قيمة \\(f_{yx}(1, 2)\\)؟",o:["\\(-7\\)","\\(+7\\)","\\(0\\)","Cannot be determined without \\(f_{xx}\\)"],o_ar:["\\(-7\\)","\\(+7\\)","\\(0\\)","لا يمكن تحديدها دون معرفة \\(f_{xx}\\)"],a:0,ex:"By Clairaut’s Theorem, continuity of \\(f_{xy}\\) and \\(f_{yx}\\) guarantees \\(f_{yx}(1, 2) = f_{xy}(1, 2) = -7\\).",ex_ar:"بحسب مبرهنة كليرو، اتصال المشتقات الجزئية الثانية يضمن تساوي \\(f_{yx}(1, 2) = f_{xy}(1, 2) = -7\\)."}];D["mvc-chain-rule"]=[{t:"sb",ti:"Lab Step Builder: Directional Derivative & Gradient",ti_ar:"بناء خطوات المعمل: المشتقة الاتجاهية والتدرج",steps:[{l:"For \\(f(x,y) = x^2 + 3y^2\\) at \\(P(1,2)\\), compute \\(f_x(1,2) = 2(1) =\\)",a:"2",h:"\\(2(1) = 2\\)"},{l:"Compute \\(f_y(1,2) = 6(2) =\\)",a:"12",h:"\\(6(2) = 12\\)"},{l:"The gradient vector is \\(\\nabla f(1,2) = \\langle 2, 12 \\rangle\\). What is the maximum directional derivative value \\(\\|\\nabla f\\|\\)? \\(\\sqrt{2^2 + 12^2} = \\sqrt{148} = 2\\sqrt{\\\text{?}}\\):",a:"37",h:"\\(148 = 4 \\\times 37\\)"}],steps_ar:[{l:"للدالة \\(f(x,y) = x^2 + 3y^2\\) عند \\(P(1,2)\\)، احسب \\(f_x(1,2) = 2(1) =\\)",a:"2",h:"\\(2(1) = 2\\)"},{l:"احسب \\(f_y(1,2) = 6(2) =\\)",a:"12",h:"\\(6(2) = 12\\)"},{l:"متجه التدرج هو \\(\\nabla f(1,2) = \\langle 2, 12 \\rangle\\). ما هي أقصى قيمة للمشتقة الاتجاهية \\(\\|\\nabla f\\|\\)؟ \\(\\sqrt{2^2 + 12^2} = \\sqrt{148} = 2\\sqrt{\\\text{?}}\\):",a:"37",h:"\\(148 = 4 \\\times 37\\)"}]},{t:"tf",ti:"Reasoning Lab: Directional Derivatives & Gradient Direction",ti_ar:"معمل الاستنتاج: المشتقات الاتجاهية واتجاه التدرج",items:[{s:"The gradient vector \\(\\nabla f(x,y)\\) always points in the direction of steepest ascent.",a:true,ex:"The maximum rate of change occurs when the unit direction vector \\(\\mathbf{u}\\) is parallel to \\(\\nabla f\\)."},{s:"The directional derivative in a direction tangent to a level curve is zero.",a:true,ex:"Along a level curve \\(f(x,y) = c\\), the value is constant, so \\(D_{\\mathbf{u}} f = \\nabla f \\cdot \\mathbf{u} = 0\\)."},{s:"The gradient \\(\\nabla f(x_0, y_0)\\) is tangent to the level curve through \\((x_0, y_0)\\).",a:false,ex:"The gradient is strictly ORTHOGONAL (perpendicular) to the level curve."}],items_ar:[{s:"يشير متجه التدرج \\(\\nabla f(x,y)\\) دائماً إلى اتجاه أقصى صعود.",ex:"يحدث أقصى معدل للتغير عندما يكون متجه اتجاه الوحدة \\(\\mathbf{u}\\) موازياً لـ \\(\\nabla f\\).",a:true},{s:"المشتقة الاتجاهية في اتجاه مماس لمنحنى المستوى تساوي صفراً.",ex:"على طول منحنى المستوى \\(f(x,y) = c\\)، القيمة ثابتة، وبالتالي \\(D_{\\mathbf{u}} f = \\nabla f \\cdot \\mathbf{u} = 0\\).",a:true},{s:"متجه التدرج \\(\\nabla f(x_0, y_0)\\) مماس لمنحنى المستوى المار بالنقطة \\((x_0, y_0)\\).",ex:"متجه التدرج عمودي تماماً على منحنى المستوى.",a:false}]},{t:"qc",ti:"Quick Check: Gradient at a Stationary Point",ti_ar:"فحص سريع: التدرج عند نقطة ساكنة",q:"If \\(f(x, y)\\) is differentiable and \\(\\nabla f(x_0, y_0) = \\langle 0, 0 \\rangle\\), what is the directional derivative \\(D_{\\mathbf{u}}f(x_0, y_0)\\) in any arbitrary unit direction \\(\\mathbf{u}\\)?",q_ar:"إذا كانت \\(f(x, y)\\) دالة قابلة للتفاضل وكان \\(\\nabla f(x_0, y_0) = \\langle 0, 0 \\rangle\\)، فما هي المشتقة الاتجاهية \\(D_{\\mathbf{u}}f(x_0, y_0)\\) في أي اتجاه وحدة اختياري \\(\\mathbf{u}\\)?",o:["0","1","\\(\\|\\mathbf{u}\\|\\)","Undefined"],o_ar:["0","1","\\(\\|\\mathbf{u}\\|\\)","غير معرّف"],a:0,ex:"Since \\(D_{\\mathbf{u}}f = \\nabla f \\cdot \\mathbf{u} = \\langle 0, 0 \\rangle \\cdot \\mathbf{u} = 0\\), the directional derivative is zero in all directions.",ex_ar:"بما أن \\(D_{\\mathbf{u}}f = \\nabla f \\cdot \\mathbf{u} = \\langle 0, 0 \\rangle \\cdot \\mathbf{u} = 0\\)، فإن المشتقة الاتجاهية تساوي صفراً في جميع الاتجاهات."},{t:"num",ti:"Maximum Rate of Change (Gradient Norm)",ti_ar:"أقصى معدل للتغير (معيار التدرج)",q:"Compute the maximum rate of increase \\(\\|\\nabla f(3, 4)\\|\\) for the function \\(f(x, y) = x^2 + y^2\\):",q_ar:"احسب أقصى معدل للزيادة \\(\\|\\nabla f(3, 4)\\|\\) للدالة \\(f(x, y) = x^2 + y^2\\):",a:10,tol:.001,h:"∇f = ⟨2x, 2y⟩. At (3, 4), ∇f = ⟨6, 8⟩. Compute √(6² + 8²).",h_ar:"∇f = ⟨2x, 2y⟩. عند (3, 4)، ∇f = ⟨6, 8⟩. احسب √(6² + 8²).",sol:"‖∇f(3, 4)‖ = √(6² + 8²) = √(36 + 64) = √100 = 10.",sol_ar:"‖∇f(3, 4)‖ = √(6² + 8²) = √(36 + 64) = √100 = 10."},{t:"ord",ti:"Order the Steps: Calculate Directional Derivative D_u f",ti_ar:"ترتيب الخطوات: حساب المشتقة الاتجاهية D_u f",q:"Order the steps to compute the directional derivative of f(x, y) at P(x₀, y₀) in the direction of vector v:",q_ar:"رتّب خطوات حساب المشتقة الاتجاهية للدالة f(x, y) عند النقطة P(x₀, y₀) في اتجاه المتجه v:",items:["Compute partial derivatives f_x and f_y to construct gradient vector ∇f","Evaluate gradient vector at the specified point: ∇f(x₀, y₀)","Calculate the length of the direction vector: ‖v‖ = √(v₁² + v₂²)","Normalize v to obtain a unit vector: u = v / ‖v‖","Take the dot product: D_u f = ∇f(x₀, y₀) · u"],items_ar:["حساب المشتقات الجزئية f_x و f_y لتكوين متجه التدرج ∇f","تعويض النقطة المحددة في متجه التدرج: ∇f(x₀, y₀)","حساب طول متجه الاتجاه: ‖v‖ = √(v₁² + v₂²)","تطبيع المتجه v للحصول على متجه وحدة: u = v / ‖v‖","حساب الضرب القياسي: D_u f = ∇f(x₀, y₀) · u"],sol:"Directional derivative requires dotting the evaluated gradient with a normalized unit direction vector.",sol_ar:"تتطلب المشتقة الاتجاهية إجراء ضرب قياسي بين متجه التدرج المحسوب ومتجه الوحدة المقابل."},{t:"cat",ti:"Classify Directional Derivative Rates of Change",ti_ar:"تصنيف معدلات التغير للمشتقة الاتجاهية",categories:["Maximum Rate of Increase (+‖∇f‖)","Maximum Rate of Decrease (-‖∇f‖)","Zero Rate of Change (0)"],categories_ar:["أقصى معدل زيادة (+‖∇f‖)","أقصى معدل تناقص (-‖∇f‖)","معدل تغير صفري (0)"],items:[{s:"Direction parallel to ∇f(x₀, y₀)",cat:0},{s:"Direction opposite to -∇f(x₀, y₀)",cat:1},{s:"Direction tangent to the level curve through (x₀, y₀)",cat:2},{s:"Direction orthogonal (perpendicular) to ∇f(x₀, y₀)",cat:2},{s:"Unit direction u = ∇f / ‖∇f‖",cat:0}],items_ar:[{s:"الاتجاه الموازي لمتجه التدرج ∇f(x₀, y₀)",cat:0},{s:"الاتجاه المعاكس لمتجه التدرج -∇f(x₀, y₀)",cat:1},{s:"الاتجاه المماس لمنحنى المستوى المار بالنقطة (x₀, y₀)",cat:2},{s:"الاتجاه العمودي على متجه التدرج ∇f(x₀, y₀)",cat:2},{s:"متجه اتجاه الوحدة u = ∇f / ‖∇f‖",cat:0}],sol:"Directional derivative is maximized in direction of ∇f, minimized in direction of -∇f, and vanishes tangent to level curves.",sol_ar:"تصل المشتقة الاتجاهية إلى أقصاها في اتجاه ∇f، وإلى أدناها في اتجاه -∇f، وتنعدم مماسياً لمنحنيات المستوى."},{t:"se",ti:"Spot the Error: Unit Vector Normalization in Directional Derivatives",ti_ar:"اكتشف الخطأ: توحيد متجه الاتجاه في المشتقة الاتجاهية",q:"Given \\(\\nabla f(1, 2) = \\langle 4, -2 \\rangle\\), a student computes the directional derivative of \\(f\\) in the direction of \\(\\mathbf{v} = \\langle 3, 4 \\rangle\\). Which step is flawed?",q_ar:"إذا كان \\(\\nabla f(1, 2) = \\langle 4, -2 \\rangle\\)، يحسب طالب المشتقة الاتجاهية في اتجاه \\(\\mathbf{v} = \\langle 3, 4 \\rangle\\). أي خطوة خاطئة؟",steps:["Write directional derivative formula \\(D_{\\mathbf{u}} f = \\nabla f \\cdot \\mathbf{u}\\).","Substitute \\(\\mathbf{v} = \\langle 3, 4 \\rangle\\) directly without dividing by \\(\\|\\mathbf{v}\\| = 5\\).","Compute dot product \\(4(3) + (-2)(4) = 12 - 8 = 4\\).","Report \\(D_{\\mathbf{v}} f(1, 2) = 4\\)."],steps_ar:["كتابة صيغة المشتقة الاتجاهية \\(D_{\\mathbf{u}} f = \\nabla f \\cdot \\mathbf{u}\\).","التعويض بالمتجه \\(\\langle 3, 4 \\rangle\\) مباشرة دون قسمته على طوله \\(\\|\\mathbf{v}\\| = 5\\).","حساب الضرب القياسي \\(12 - 8 = 4\\).","كتابة الناتج \\(4\\)."],errorStep:2,reasons:["\\(D_{\\mathbf{u}} f = \\nabla f \\cdot \\mathbf{u}\\) requires a UNIT vector \\(\\mathbf{u} = \\mathbf{v}/\\|\\mathbf{v}\\| = \\langle 3/5, 4/5 \\rangle\\), giving \\(4/5 = 0.8\\).","Directional derivatives use the cross product \\(\\nabla f \\times \\mathbf{u}\\).","\\(\\|\\langle 3, 4 \\rangle\\|\\) equals \\(7\\), not \\(5\\)."],reasons_ar:["تشترط صيغة \\(D_{\\mathbf{u}} f\\) متجه وحدة \\(\\mathbf{u} = \\langle 3/5, 4/5 \\rangle\\)، فيكون الناتج الصحيح \\(4/5 = 0.8\\).","تُحسب المشتقة الاتجاهية بالضرب الاتجاهي.","طول المتجه \\(\\langle 3, 4 \\rangle\\) يساوي \\(7\\)."],correctReason:0},{t:"ms",ti:"Examiner Mode: Gradient Vector & Hessian Classification (The Multivariable Chain Rule, Directional Derivatives & Gradient Geometry)",ti_ar:"وضع المصحح: متجه التدرج ومصفوفة هيس (قاعدة السلسلة متعددة المتغيرات والمشتقات الاتجاهية وهندسة التدرج)",q:"Let \\(f(x, y) = 2x^2 + 1xy + y^2\\). (a) Compute \\(\\nabla f(1, 2)\\). (b) Compute the Hessian determinant \\(D = f_{xx}f_{yy} - (f_{xy})^2\\).",q_ar:"لتكن \\(f(x, y) = 2x^2 + 1xy + y^2\\). (أ) احسب متجه التدرج \\(\\nabla f(1, 2)\\). (ب) احسب محدد هيس \\(D = f_{xx}f_{yy} - (f_{xy})^2\\).",parts:[{label:"Part (a) — Partial Derivatives & Gradient",marks:2,rubric:[{code:"M1",marks:1,text:"\\(f_x = 4x + 1y,\\quad f_y = 1x + 2y\\)."},{code:"A1",marks:1,text:"At \\((1, 2)\\): \\(\\nabla f(1, 2) = \\langle 6, 5 \\rangle\\)."}]},{label:"Part (b) — Second-Derivative Discriminant",marks:2,rubric:[{code:"M1",marks:1,text:"\\(f_{xx} = 4,\\; f_{yy} = 2,\\; f_{xy} = 1\\)."},{code:"A1",marks:1,text:"\\(D = (4)(2) - 1^2 = 7\\)."}]}],parts_ar:[{label:"الجزء (أ) — المشتقات الجزئية ومتجه التدرج",marks:2,rubric:[{code:"M1",marks:1,text:"\\(f_x = 4x + 1y,\\quad f_y = 1x + 2y\\)."},{code:"A1",marks:1,text:"عند \\((1, 2)\\): \\(\\nabla f(1, 2) = \\langle 6, 5 \\rangle\\)."}]},{label:"الجزء (ب) — محدد المشتقات الجزئية الثانية (هيس)",marks:2,rubric:[{code:"M1",marks:1,text:"\\(f_{xx} = 4,\\; f_{yy} = 2,\\; f_{xy} = 1\\)."},{code:"A1",marks:1,text:"\\(D = 7\\)."}]}]},{t:"mt",ti:"Matching: Partial Derivatives, Tangent Planes & Gradient Geometry",ti_ar:"مطابقة: المشتقات الجزئية والمستوى المماس وهندسة التدرج",p:[{l:"Gradient vector \\(\\nabla f(x, y)\\)",r:"\\(\\langle f_x(x, y),\\; f_y(x, y) \\rangle\\), orthogonal to level curves"},{l:"Tangent plane to \\(z = f(x, y)\\) at \\((a, b)\\)",r:"\\(z = f(a,b) + f_x(a,b)(x - a) + f_y(a,b)(y - b)\\)"},{l:"Clairaut’s theorem for \\(C^2\\) functions",r:"Mixed partials commute: \\(f_{xy} = f_{yx}\\)"},{l:"Directional derivative \\(D_{\\mathbf{u}} f\\) (unit \\(\\mathbf{u}\\))",r:"\\(\\nabla f \\cdot \\mathbf{u} = \\|\\nabla f\\|\\cos\\theta\\)"}],p_ar:[{l:"متجه التدرج \\(\\nabla f(x, y)\\)",r:"\\(\\langle f_x, f_y \\rangle\\) عمودي على منحنيات المستوى"},{l:"المستوى المماس للسطح \\(z = f(x, y)\\)",r:"\\(z = f(a,b) + f_x(a,b)(x - a) + f_y(a,b)(y - b)\\)"},{l:"مبرهنة كليرو للدوال المتصلة \\(C^2\\)",r:"تساوي المشتقات المختلطة \\(f_{xy} = f_{yx}\\)"},{l:"المشتقة الاتجاهية \\(D_{\\mathbf{u}} f\\)",r:"\\(\\nabla f \\cdot \\mathbf{u} = \\|\\nabla f\\|\\cos\\theta\\)"}]}];D["mvc-optimization"]=[{t:"sb",ti:"Lab Step Builder: Second Derivative Test for Critical Points",ti_ar:"بناء خطوات المعمل: اختبار المشتقة الثانية للنقاط الحرجة",steps:[{l:"Discriminant \\(D = f_{xx} f_{yy} - (f_{xy})^2\\). If \\(f_{xx} = 4\\), \\(f_{yy} = 3\\), and \\(f_{xy} = 1\\), compute \\(D = 4(3) - 1^2 =\\)",a:"11",h:"\\(12 - 1 = 11\\)"},{l:"Since \\(D > 0\\) and \\(f_{xx} > 0\\), the critical point is a local: (min/max/saddle)",a:"min",h:"Positive D and positive f_xx indicates a local minimum."}],steps_ar:[{l:"المميز \\(D = f_{xx} f_{yy} - (f_{xy})^2\\). إذا كانت \\(f_{xx} = 4\\)، و\\(f_{yy} = 3\\)، و\\(f_{xy} = 1\\)، فاحسب \\(D = 4(3) - 1^2 =\\)",a:"11",h:"\\(12 - 1 = 11\\)"},{l:"بما أن \\(D > 0\\) و \\(f_{xx} > 0\\)، فإن النقطة الحرجة هي نقطة: (min/max/saddle)",a:"min",h:"D موجب و f_xx موجب يشيران إلى قيمة صغرى محلية."}]},{t:"mt",ti:"Matching Lab: Second Derivative Test Outcomes",ti_ar:"معمل المطابقة: نتائج اختبار المشتقة الثانية",p:[{l:"D > 0 and f_xx > 0",r:"Local minimum"},{l:"D > 0 and f_xx < 0",r:"Local maximum"},{l:"D < 0",r:"Saddle point"},{l:"D = 0",r:"Inconclusive"}],p_ar:[{l:"D > 0 و f_xx > 0",r:"قيمة صغرى محلية"},{l:"D > 0 و f_xx < 0",r:"قيمة عظمى محلية"},{l:"D < 0",r:"نقطة سرج (Saddle point)"},{l:"D = 0",r:"الاختبار غير حاسم"}]},{t:"qc",ti:"Quick Check: Lagrange Multipliers Tangency",ti_ar:"فحص سريع: تماس مضاعفات لاغرانج",q:"At an extremum of \\(f(x, y)\\) subject to constraint \\(g(x, y) = k\\), the gradient vectors satisfy:",q_ar:"عند النقطة القصوى للدالة \\(f(x, y)\\) الخاضعة للقيد \\(g(x, y) = k\\)، يحقق متجها التدرج العلاقة:",o:["\\(\\nabla f = \\lambda \\nabla g\\)","\\(\\nabla f \\cdot \\nabla g = 0\\)","\\(\\nabla f = -\\nabla g\\) always","\\(\\nabla f = \\mathbf{0}\\)"],o_ar:["\\(\\nabla f = \\lambda \\nabla g\\)","\\(\\nabla f \\cdot \\nabla g = 0\\)","\\(\\nabla f = -\\nabla g\\) دائماً","\\(\\nabla f = \\mathbf{0}\\)"],a:0,ex:"Extrema occur where the level curve of f is tangent to the constraint curve g=k, meaning their normal gradients are collinear: \\(\\nabla f = \\lambda \\nabla g\\).",ex_ar:"تحدث القيم القصوى عندما يمس منحنى مستوى f منحنى القيد g=k، مما يعني أن متجهات التدرج العمودية تكون متوازية خطياً: \\(\\nabla f = \\lambda \\nabla g\\)."},{t:"num",ti:"Compute Hessian Discriminant D",ti_ar:"حساب مميز هيسيان D",q:"At a critical point of \\(f(x, y)\\), the second partials are \\(f_{xx} = 6\\), \\(f_{yy} = 4\\), and \\(f_{xy} = 3\\). Compute the discriminant \\(D = f_{xx}f_{yy} - (f_{xy})^2\\):",q_ar:"عند نقطة حرجة للدالة \\(f(x, y)\\)، المشتقات الجزئية الثانية هي \\(f_{xx} = 6\\)، و\\(f_{yy} = 4\\)، و\\(f_{xy} = 3\\). احسب المميز \\(D = f_{xx}f_{yy} - (f_{xy})^2\\):",a:15,tol:.001,h:"D = 6(4) - 3² = 24 - 9.",h_ar:"D = 6(4) - 3² = 24 - 9.",sol:"D = 6(4) - 9 = 24 - 9 = 15.",sol_ar:"D = 6(4) - 9 = 24 - 9 = 15."},{t:"ord",ti:"Order the Steps: Second Derivative Test Classification",ti_ar:"ترتيب الخطوات: تصنيف النقاط باختبار المشتقة الثانية",q:"Order the steps to locate and classify the local extrema of a smooth function f(x, y):",q_ar:"رتّب خطوات تحديد وتصنيف القيم القصوى المحلية لدالة ملساء f(x, y):",items:["Find first partial derivatives f_x and f_y and set both equal to 0","Solve the system f_x = 0 and f_y = 0 simultaneously to find all critical points","Compute second partial derivatives f_xx, f_yy, and f_xy","Form the discriminant D(x, y) = f_xx f_yy - (f_xy)²","Evaluate D at each critical point: if D < 0 saddle; if D > 0 check sign of f_xx"],items_ar:["إيجاد المشتقات الجزئية الأولى f_x و f_y ومساواة كلتيهما بالصفر","حل النظام f_x = 0 و f_y = 0 معاً لتحديد جميع النقاط الحرجة","حساب المشتقات الجزئية من الرتبة الثانية f_xx و f_yy و f_xy","تكوين دالة المميز D(x, y) = f_xx f_yy - (f_xy)²","حساب قيمة D عند كل نقطة حرجة: إذا كانت D < 0 فنقطة سرج؛ وإذا كانت D > 0 نحدد إشارة f_xx"],sol:"Critical points are found via first derivatives, then classified via the sign of D and f_xx.",sol_ar:"يتم تحديد النقاط الحرجة بواسطة المشتقات الأولى، ثم تصنيفها بناءً على إشارة D و f_xx."},{t:"cat",ti:"Classify Optimization Conditions: Unconstrained vs. Constrained",ti_ar:"تصنيف شروط الأمثلية: غير المقيدة مقابل المقيدة",categories:["Unconstrained Extrema Condition","Lagrange Multiplier Constrained Condition"],categories_ar:["شرط القيم القصوى غير المقيدة","شرط مضاعفات لاغرانج المقيدة"],items:[{s:"∇f(x, y) = ⟨0, 0⟩",cat:0},{s:"∇f(x, y) = λ ∇g(x, y) with constraint g(x, y) = k",cat:1},{s:"f_x = 0 and f_y = 0 simultaneously",cat:0},{s:"Level curves of f are tangent to constraint boundary g = k",cat:1},{s:"Curvature classified via discriminant D = f_xx f_yy - (f_xy)²",cat:0}],items_ar:[{s:"∇f(x, y) = ⟨0, 0⟩",cat:0},{s:"∇f(x, y) = λ ∇g(x, y) مع القيد g(x, y) = k",cat:1},{s:"f_x = 0 و f_y = 0 في وقت واحد",cat:0},{s:"منحنيات مستوى f مماسية لحدود القيد g = k",cat:1},{s:"تصنيف الانحناء عبر المميز D = f_xx f_yy - (f_xy)²",cat:0}],sol:"Unconstrained optimization looks for flat tangent planes (∇f = 0); Lagrange multipliers looks for tangency with constraint curves.",sol_ar:"تبحث الأمثلية غير المقيدة عن مستويات مماسية أفقية (∇f = 0)؛ بينما تبحث طريقة لاغرانج عن التماس مع منحنيات القيد."},{t:"se",ti:"Spot the Error: Hessian Determinant Sign in 2D Critical-Point Classification",ti_ar:"اكتشف الخطأ: إشارة محدد هيسيان في تصنيف النقاط الحرجة",q:"At a critical point \\((a, b)\\) where \\(\\nabla f = \\mathbf{0}\\), \\(f_{xx} = -4\\), \\(f_{yy} = 2\\), and \\(f_{xy} = 1\\), a student classifies \\((a, b)\\). Which step is invalid?",q_ar:"عند نقطة حرجة \\(\\nabla f = \\mathbf{0}\\) حيث \\(f_{xx} = -4\\) و\\(f_{yy} = 2\\) و\\(f_{xy} = 1\\)، يصنف طالب النقطة. أي خطوة غير صحيحة؟",steps:["Confirm first partials vanish: \\(f_x(a, b) = 0\\) and \\(f_y(a, b) = 0\\).","Compute Hessian discriminant \\(D = f_{xx}f_{yy} - (f_{xy})^2 = (-4)(2) - 1^2 = -9\\).","Because \\(f_{xx} = -4 < 0\\), conclude \\((a, b)\\) is a local maximum despite \\(D < 0\\).","Record a local maximum at \\((a, b)\\)."],steps_ar:["التحقق من انعدام المشتقات الجزئية الأولى.","حساب المميز \\(D = f_{xx}f_{yy} - (f_{xy})^2 = (-4)(2) - 1 = -9\\).","الاستنتاج بأن النقطة نهاية عظمى محلية لأن \\(f_{xx} < 0\\) رغم أن \\(D < 0\\).","تسجيل النقطة كنهاية عظمى محلية."],errorStep:3,reasons:["Whenever \\(D < 0\\), the surface curves upward in one direction and downward in another, so \\((a, b)\\) is a SADDLE POINT; \\(f_{xx} < 0\\) gives a local max only when \\(D > 0\\).","The Hessian discriminant is \\(f_{xx} + f_{yy}\\).","\\(D = -9\\) means the second derivative test is inconclusive."],reasons_ar:["عندما يكون \\(D < 0\\) تكون النقطة الحرجة نقطة سرجية دائماً؛ ولا ننظر لإشارة \\(f_{xx}\\) للنهاية العظمى إلا عندما يكون \\(D > 0\\).","مميز هيسيان يساوي \\(f_{xx} + f_{yy}\\).","كون \\(D = -9\\) يعني أن الاختبار غير حاسم."],correctReason:0},{t:"ms",ti:"Examiner Mode: Gradient Vector & Hessian Classification (Multivariable Optimization: Critical Points, Hessians & Lagrange Multipliers)",ti_ar:"وضع المصحح: متجه التدرج ومصفوفة هيس (التحسين متعدد المتغيرات: النقاط الحرجة ومصفوفة هيس ومضاعفات لاغرانج)",q:"Let \\(f(x, y) = 3x^2 + 2xy + y^2\\). (a) Compute \\(\\nabla f(1, 2)\\). (b) Compute the Hessian determinant \\(D = f_{xx}f_{yy} - (f_{xy})^2\\).",q_ar:"لتكن \\(f(x, y) = 3x^2 + 2xy + y^2\\). (أ) احسب متجه التدرج \\(\\nabla f(1, 2)\\). (ب) احسب محدد هيس \\(D = f_{xx}f_{yy} - (f_{xy})^2\\).",parts:[{label:"Part (a) — Partial Derivatives & Gradient",marks:2,rubric:[{code:"M1",marks:1,text:"\\(f_x = 6x + 2y,\\quad f_y = 2x + 2y\\)."},{code:"A1",marks:1,text:"At \\((1, 2)\\): \\(\\nabla f(1, 2) = \\langle 10, 6 \\rangle\\)."}]},{label:"Part (b) — Second-Derivative Discriminant",marks:2,rubric:[{code:"M1",marks:1,text:"\\(f_{xx} = 6,\\; f_{yy} = 2,\\; f_{xy} = 2\\)."},{code:"A1",marks:1,text:"\\(D = (6)(2) - 2^2 = 8\\)."}]}],parts_ar:[{label:"الجزء (أ) — المشتقات الجزئية ومتجه التدرج",marks:2,rubric:[{code:"M1",marks:1,text:"\\(f_x = 6x + 2y,\\quad f_y = 2x + 2y\\)."},{code:"A1",marks:1,text:"عند \\((1, 2)\\): \\(\\nabla f(1, 2) = \\langle 10, 6 \\rangle\\)."}]},{label:"الجزء (ب) — محدد المشتقات الجزئية الثانية (هيس)",marks:2,rubric:[{code:"M1",marks:1,text:"\\(f_{xx} = 6,\\; f_{yy} = 2,\\; f_{xy} = 2\\)."},{code:"A1",marks:1,text:"\\(D = 8\\)."}]}]},{t:"qc",ti:"Quick Check: Lagrange Multipliers Optimality Condition",ti_ar:"فحص سريع: شرط مضروبات لاغرانج للتحسين المقيد",q:"To maximize \\(f(x, y)\\) subject to smooth constraint \\(g(x, y) = c\\) (with \\(\\nabla g \\neq \\mathbf{0}\\)), what geometric condition holds at an interior constrained extremum?",q_ar:"لتعظيم \\(f(x, y)\\) تحت القيد \\(g(x, y) = c\\)، ما الشرط الهندسي المتحقق عند نقطة القيمة القصوى المقيدة؟",o:["\\(\\nabla f = \\lambda \\nabla g\\) (the gradients of \\(f\\) and \\(g\\) are parallel)","\\(\\nabla f \\cdot \\nabla g = 0\\) (the gradients are perpendicular)","\\(\\nabla f = \\mathbf{0}\\) unconditionally","\\(f(x, y) = \\lambda g(x, y)\\)"],o_ar:["\\(\\nabla f = \\lambda \\nabla g\\) (توازي متجهي التدرج للدالة والقيد)","\\(\\nabla f \\cdot \\nabla g = 0\\) (تعامد متجهي التدرج)","\\(\\nabla f = \\mathbf{0}\\) دائماً دون قيد","\\(f(x, y) = \\lambda g(x, y)\\)"],a:0,ex:"At a constrained extremum, the level curve of \\(f\\) is tangent to \\(g(x, y) = c\\), so their normal vectors \\(\\nabla f\\) and \\(\\nabla g\\) are parallel: \\(\\nabla f = \\lambda \\nabla g\\).",ex_ar:"عند القيمة القصوى المقيدة يمس منحنى مستوى \\(f\\) منحنى القيد \\(g = c\\)، فيتوازى المتجهان العموديان \\(\\nabla f = \\lambda \\nabla g\\)."}];D["mvc-double-integrals"]=[{t:"sb",ti:"Lab Step Builder: Iterated Double Integrals",ti_ar:"بناء خطوات المعمل: التكاملات الثنائية المتكررة",steps:[{l:"Evaluate \\(int_0^1 int_0^2 (2x + 3y),dy,dx\\). Inner integral with respect to y: \\([2xy + \\frac{3}{2}y^2]_0^2 = 4x +\\)",a:"6",h:"\\(2x(2) + 3/2(4) = 4x + 6\\)"},{l:"Outer integral with respect to x: \\(int_0^1 (4x + 6),dx = [2x^2 + 6x]_0^1 =\\)",a:"8",h:"\\(2(1) + 6(1) = 8\\)"}],steps_ar:[{l:"احسب \\(int_0^1 int_0^2 (2x + 3y),dy,dx\\). التكامل الداخلي بالنسبة إلى y هو: \\([2xy + \\frac{3}{2}y^2]_0^2 = 4x +\\)",a:"6",h:"\\(2x(2) + 3/2(4) = 4x + 6\\)"},{l:"التكامل الخارجي بالنسبة إلى x هو: \\(int_0^1 (4x + 6),dx = [2x^2 + 6x]_0^1 =\\)",a:"8",h:"\\(2(1) + 6(1) = 8\\)"}]},{t:"qc",ti:"Lab Check: Double Integrals in Polar Coordinates",ti_ar:"فحص المعمل: التكاملات الثنائية بالإحداثيات القطبية",q:"When converting a double integral \\(iint_R f(x,y),dA\\) to polar coordinates, the area element \\(dA\\) becomes:",q_ar:"عند تحويل التكامل الثنائي \\(iint_R f(x,y),dA\\) إلى الإحداثيات القطبية، يصبح عنصر المساحة \\(dA\\):",o:["\\(r,dr,d\\theta\\)","\\(dr,d\\theta\\)","\\(r^2,dr,d\\theta\\)","\\(\\frac{1}{r},dr,d\\theta\\)"],o_ar:["\\(r,dr,d\\theta\\)","\\(dr,d\\theta\\)","\\(r^2,dr,d\\theta\\)","\\(\\frac{1}{r},dr,d\\theta\\)"],a:0,ex:"The Jacobian determinant of the transformation \\(x=rcos\\theta, y=rsin\\theta\\) is \\(r\\), giving \\(dA = r,dr,d\\theta\\).",ex_ar:"محدد مصفوفة جاكوبي لتحويل الإحداثيات \\(x=rcos\\theta, y=rsin\\theta\\) هو \\(r\\)، مما يعطي \\(dA = r,dr,d\\theta\\)."},{t:"mt",ti:"Matching: Double Integral Regions and Slices",ti_ar:"معمل المطابقة: مناطق وشرائح التكامل الثنائي",p:[{l:"Type I region",r:"Integrated dy first, between curves y = g₁(x) and y = g₂(x)"},{l:"Type II region",r:"Integrated dx first, between curves x = h₁(y) and x = h₂(y)"},{l:"Fubini's Theorem",r:"Allows swapping order of integration for continuous f"},{l:"Area of region D",r:"∬_D 1 dA"}],p_ar:[{l:"منطقة من النوع الأول (Type I)",r:"التكامل بالنسبة إلى dy أولاً، بين المنحنيين y = g₁(x) و y = g₂(x)"},{l:"منطقة من النوع الثاني (Type II)",r:"التكامل بالنسبة إلى dx أولاً، بين المنحنيين x = h₁(y) و x = h₂(y)"},{l:"مبرهنة فوبيني (Fubini)",r:"تسمح بتبديل ترتيب التكامل للدوال المستمرة f"},{l:"مساحة المنطقة D",r:"∬_D 1 dA"}]},{t:"num",ti:"Separable Double Integral Calculation",ti_ar:"حساب التكامل الثنائي القابل للفصل",q:"Evaluate the separable double integral \\(int_0^2 int_0^3 xy , dy , dx\\):",q_ar:"احسب قيمة التكامل الثنائي القابل للفصل \\(int_0^2 int_0^3 xy , dy , dx\\):",a:9,tol:.001,h:"Factor into (∫₀² x dx)(∫₀³ y dy) = [x²/2]₀² · [y²/2]₀³ = 2 · (9/2).",h_ar:"افصل التكامل إلى (∫₀² x dx)(∫₀³ y dy) = [x²/2]₀² · [y²/2]₀³ = 2 · (9/2).",sol:"(2) · (9/2) = 9.",sol_ar:"(2) · (9/2) = 9."},{t:"ord",ti:"Order the Steps: Convert Double Integral to Polar Coordinates",ti_ar:"ترتيب الخطوات: تحويل التكامل الثنائي إلى الإحداثيات القطبية",q:"Order the steps to convert and evaluate a double integral ∬_D f(x, y) dA using polar coordinates:",q_ar:"رتّب خطوات تحويل وحساب التكامل الثنائي ∬_D f(x, y) dA باستخدام الإحداثيات القطبية:",items:["Sketch region D and determine radial limits r₁ ≤ r ≤ r₂ and angle limits θ₁ ≤ θ ≤ θ₂","Substitute x = r cos θ and y = r sin θ into the integrand f(x, y)","Replace the area element dA with the polar area element r dr dθ","Integrate with respect to r from inner boundary to outer boundary","Integrate the resulting expression with respect to θ over the angular interval"],items_ar:["رسم المنطقة D وتحديد حدود نصف القطر r₁ ≤ r ≤ r₂ وحدود الزاوية θ₁ ≤ θ ≤ θ₂","التعويض بـ x = r cos θ و y = r sin θ في دالة المكاملة f(x, y)","استبدال عنصر المساحة dA بعنصر المساحة القطبي r dr dθ","إجراء التكامل بالنسبة إلى r من الحد الداخلي إلى الحد الخارجي","حساب تكامل المقدار الناتج بالنسبة إلى θ على الفترة الزاوية"],sol:"Polar conversion requires replacing coordinates, inserting Jacobian factor r, and evaluating iterated limits.",sol_ar:"يتطلب التحويل القطبي استبدال الإحداثيات، وإدراج عامل جاكوبي r، وحساب حدود التكامل المتكرر."},{t:"cat",ti:"Classify Integration Regions: Cartesian vs. Polar Preference",ti_ar:"تصنيف مناطق التكامل: تفضيل الديكارتي مقابل القطبي",categories:["Best Solved in Cartesian Coordinates (dx dy)","Best Solved in Polar Coordinates (r dr dθ)"],categories_ar:["يُفضل حلها بالإحداثيات الديكارتية (dx dy)","يُفضل حلها بالإحداثيات القطبية (r dr dθ)"],items:[{s:"Rectangular region [a, b] × [c, d]",cat:0},{s:"Circular disk x² + y² ≤ 16",cat:1},{s:"Integrand containing (x² + y²)",cat:1},{s:"Triangular region bounded by y = 2x, y = 0, and x = 4",cat:0},{s:"Annular sector between circles r = 1 and r = 3 for 0 ≤ θ ≤ π/2",cat:1}],items_ar:[{s:"منطقة مستطيلة [a, b] × [c, d]",cat:0},{s:"قرص دائري x² + y² ≤ 16",cat:1},{s:"دالة مكاملة تحتوي على (x² + y²)",cat:1},{s:"منطقة مثلثة محصورة بين y = 2x و y = 0 و x = 4",cat:0},{s:"قطاع حلقي بين الدائرتين r = 1 و r = 3 لـ 0 ≤ θ ≤ π/2",cat:1}],sol:"Polar coordinates excel for circular, radial, and rotational boundaries; Cartesian is natural for boxes and linear boundaries.",sol_ar:"تتميز الإحداثيات القطبية في المناطق الدائرية والقطرية؛ بينما تناسب الإحداثيات الديكارتية الصناديق والحدود الخطية."},{t:"se",ti:"Spot the Error: Polar Jacobian & Mixed Partial Differentiation (Double Integrals, Fubini's Theorem, Polar Coordinates & The Change-of-Variables Jacobian)",ti_ar:"اكتشف الخطأ: جاكوبي الإحداثيات القطبية والمشتقات الجزئية (التكاملات الثنائية ونظرية فوبيني والإحداثيات القطبية والجاكوبيان)",q:"A student converts \\(\\iint_D (x^2 + y^2)\\,dA\\) over disk \\(x^2 + y^2 \\le 4\\) to polar coordinates. Where is the error?",q_ar:"يحوّل طالب التكامل الثنائي \\(\\iint_D (x^2 + y^2)\\,dA\\) على القرص \\(x^2 + y^2 \\le 4\\) إلى الإحداثيات القطبية. أين الخطأ؟",steps:["Parameterize the disk by \\(0 \\le r \\le 2\\) and \\(0 \\le \\theta \\le 2\\pi\\), with \\(x^2 + y^2 = r^2\\).","Replace \\(dA\\) directly with \\(dr\\,d\\theta\\) without the Jacobian factor \\(r\\), writing \\(\\int_0^{2\\pi}\\int_0^2 r^2\\,dr\\,d\\theta\\).","Evaluate to get \\(\\frac{16\\pi}{3}\\) instead of \\(8\\pi\\)."],steps_ar:["توصيف القرص بالحدود \\(0 \\le r \\le 2\\) و\\(0 \\le \\theta \\le 2\\pi\\) مع \\(x^2 + y^2 = r^2\\).","استبدال \\(dA\\) بـ \\(dr\\,d\\theta\\) مباشرة وإغفال معامل الجاكوبي \\(r\\).","حساب التكامل للحصول على \\(\\frac{16\\pi}{3}\\) بدلاً من \\(8\\pi\\)."],errorStep:2,reasons:["In polar coordinates the area element is \\(dA = r\\,dr\\,d\\theta\\), so the integrand becomes \\(r^2 \\cdot r = r^3\\), yielding \\(8\\pi\\).","\\(x^2 + y^2\\) equals \\(r\\), not \\(r^2\\).","\\(\\theta\\) ranges only from \\(0\\) to \\(\\pi\\) for a full disk."],reasons_ar:["عنصر المساحة في الإحداثيات القطبية هو \\(dA = r\\,dr\\,d\\theta\\)، فيصبح التكامل لـ \\(r^3\\) والناتج الصحيح \\(8\\pi\\).","المقدار \\(x^2 + y^2\\) يساوي \\(r\\).","حدود \\(\\theta\\) للقرص الكامل من \\(0\\) إلى \\(\\pi\\)."],correctReason:0},{t:"ms",ti:"Examiner Mode: Gradient Vector & Hessian Classification (Double Integrals, Fubini's Theorem, Polar Coordinates & The Change-of-Variables Jacobian)",ti_ar:"وضع المصحح: متجه التدرج ومصفوفة هيس (التكاملات الثنائية ونظرية فوبيني والإحداثيات القطبية والجاكوبيان)",q:"Let \\(f(x, y) = 4x^2 + 3xy + y^2\\). (a) Compute \\(\\nabla f(1, 2)\\). (b) Compute the Hessian determinant \\(D = f_{xx}f_{yy} - (f_{xy})^2\\).",q_ar:"لتكن \\(f(x, y) = 4x^2 + 3xy + y^2\\). (أ) احسب متجه التدرج \\(\\nabla f(1, 2)\\). (ب) احسب محدد هيس \\(D = f_{xx}f_{yy} - (f_{xy})^2\\).",parts:[{label:"Part (a) — Partial Derivatives & Gradient",marks:2,rubric:[{code:"M1",marks:1,text:"\\(f_x = 8x + 3y,\\quad f_y = 3x + 2y\\)."},{code:"A1",marks:1,text:"At \\((1, 2)\\): \\(\\nabla f(1, 2) = \\langle 14, 7 \\rangle\\)."}]},{label:"Part (b) — Second-Derivative Discriminant",marks:2,rubric:[{code:"M1",marks:1,text:"\\(f_{xx} = 8,\\; f_{yy} = 2,\\; f_{xy} = 3\\)."},{code:"A1",marks:1,text:"\\(D = (8)(2) - 3^2 = 7\\)."}]}],parts_ar:[{label:"الجزء (أ) — المشتقات الجزئية ومتجه التدرج",marks:2,rubric:[{code:"M1",marks:1,text:"\\(f_x = 8x + 3y,\\quad f_y = 3x + 2y\\)."},{code:"A1",marks:1,text:"عند \\((1, 2)\\): \\(\\nabla f(1, 2) = \\langle 14, 7 \\rangle\\)."}]},{label:"الجزء (ب) — محدد المشتقات الجزئية الثانية (هيس)",marks:2,rubric:[{code:"M1",marks:1,text:"\\(f_{xx} = 8,\\; f_{yy} = 2,\\; f_{xy} = 3\\)."},{code:"A1",marks:1,text:"\\(D = 7\\)."}]}]},{t:"qc",ti:"Quick Check: Multivariable & Vector Integral Theorems (Double Integrals, Fubini's Theorem, Polar Coordinates & The Change-of-Variables Jacobian)",ti_ar:"فحص سريع: نظريات التفاضل والتكامل المتجهي (التكاملات الثنائية ونظرية فوبيني والإحداثيات القطبية والجاكوبيان)",q:"Which expression or condition accurately characterizes Directional derivative \\(D_{\\mathbf{u}} f\\)?",q_ar:"أي عبارة أو شرط يصف بدقة: المشتقة الاتجاهية \\(D_{\\mathbf{u}} f\\)؟",o:["\\(\\nabla f \\cdot \\mathbf{u}\\) (unit \\(\\mathbf{u}\\))","\\(\\oint_C \\mathbf{F}\\cdot d\\mathbf{r} = \\iint_D (Q_x - P_y)\\,dA\\)","\\(\\rho^2 \\sin\\varphi\\,d\\rho\\,d\\varphi\\,d\\theta\\)","\\(\\iint_{\\partial E} \\mathbf{F}\\cdot \\mathbf{n}\\,dS = \\iiint_E (\\nabla \\cdot \\mathbf{F})\\,dV\\)"],o_ar:["\\(\\nabla f \\cdot \\mathbf{u}\\) (لمتجه وحدة \\(\\mathbf{u}\\))","\\(\\oint_C \\mathbf{F}\\cdot d\\mathbf{r} = \\iint_D (Q_x - P_y)\\,dA\\)","\\(\\rho^2 \\sin\\varphi\\,d\\rho\\,d\\varphi\\,d\\theta\\)","\\(\\iint_{\\partial E} \\mathbf{F}\\cdot \\mathbf{n}\\,dS = \\iiint_E (\\nabla \\cdot \\mathbf{F})\\,dV\\)"],a:0,ex:"Directional derivative \\(D_{\\mathbf{u}} f\\) matches \\(\\nabla f \\cdot \\mathbf{u}\\) (unit \\(\\mathbf{u}\\)).",ex_ar:"المشتقة الاتجاهية \\(D_{\\mathbf{u}} f\\) يطابق \\(\\nabla f \\cdot \\mathbf{u}\\) (لمتجه وحدة \\(\\mathbf{u}\\))."}];D["mvc-triple-integrals"]=[{t:"mt",ti:"Matching Lab: Differential Volume Elements in Coordinates",ti_ar:"معمل المطابقة: عناصر الحجم التفاضلية في أنظمة الإحداثيات",p:[{l:"Cartesian volume element dV",r:"dx dy dz"},{l:"Cylindrical volume element dV",r:"r dz dr dθ"},{l:"Spherical volume element dV",r:"ρ² sin φ dρ dφ dθ"},{l:"Spherical radius relation",r:"x² + y² + z² = ρ²"}],p_ar:[{l:"عنصر الحجم الديكارتي dV",r:"dx dy dz"},{l:"عنصر الحجم الأسطواني dV",r:"r dz dr dθ"},{l:"عنصر الحجم الكروي dV",r:"ρ² sin φ dρ dφ dθ"},{l:"علاقة نصف القطر الكروي",r:"x² + y² + z² = ρ²"}]},{t:"qc",ti:"Lab Check: Spherical Angle Conventions",ti_ar:"فحص المعمل: اصطلاحات الزوايا الكروية",q:"In spherical coordinates \\((\\rho, \\\theta, \\phi)\\), the polar/zenith angle \\(phi\\) measured from the positive z-axis ranges from:",q_ar:"في الإحداثيات الكروية \\((\\rho, \\\theta, \\phi)\\)، يتراوح مدى زاوية السمت/القطب \\(phi\\) المقاسة من الاتجاه الموجب لمحور z بين:",o:["\\([0, \\pi]\\)","\\([0, 2\\pi]\\)","\\([-\\pi/2, \\pi/2]\\)","\\([0, \\pi/2]\\)"],o_ar:["\\([0, \\pi]\\)","\\([0, 2\\pi]\\)","\\([-\\pi/2, \\pi/2]\\)","\\([0, \\pi/2]\\)"],a:0,ex:"\\(phi = 0\\) represents the north pole (positive z-axis) and \\(phi = \\pi\\) represents the south pole (negative z-axis).",ex_ar:"تمثل \\(phi = 0\\) القطب الشمالي (محور z الموجب) بينما تمثل \\(phi = \\pi\\) القطب الجنوبي (محور z السالب)."},{t:"sb",ti:"Lab Step Builder: Cylindrical Coordinates Volume Integral",ti_ar:"بناء خطوات المعمل: تكامل الحجم بالإحداثيات الأسطوانية",steps:[{l:"In cylindrical coordinates, \\(x^2 + y^2 =\\)",a:"r^2",h:"x = r cos θ, y = r sin θ gives x² + y² = r²"},{l:"The Jacobian volume element \\(dV =\\) ? \\(dz\\,dr\\,d\\\theta\\):",a:"r",h:"Jacobian factor is r"},{l:"For a solid bounded below by \\(z=0\\) and above by \\(z=4-r^2\\), the inner z-integral evaluates to \\([z]_0^{4-r^2} = 4 -\\)",a:"r^2",h:"4 - r² - 0 = 4 - r²"}],steps_ar:[{l:"في الإحداثيات الأسطوانية، \\(x^2 + y^2 =\\)",a:"r^2",h:"x = r cos θ, y = r sin θ يعطي x² + y² = r²"},{l:"عنصر الحجم التفاضلي لجاكوبي \\(dV =\\) ؟ \\(dz\\,dr\\,d\\\theta\\):",a:"r",h:"عامل جاكوبي هو r"},{l:"لمجسم يحده من الأسفل \\(z=0\\) ومن الأعلى \\(z=4-r^2\\)، ناتج تكامل z الداخلي هو \\([z]_0^{4-r^2} = 4 -\\)",a:"r^2",h:"4 - r² - 0 = 4 - r²"}]},{t:"num",ti:"Cylinder Volume Calculation in Cylindrical Coordinates",ti_ar:"حساب حجم أسطوانة بالإحداثيات الأسطوانية",q:"Using cylindrical coordinates, compute the volume of a cylinder of radius \\(R = 3\\) and height \\(h = 5\\) (formula \\(V = \\pi R^2 h\\); enter the integer coefficient of \\(pi\\), i.e., \\(R^2 h\\)):",q_ar:"باستخدام الإحداثيات الأسطوانية، احسب حجم أسطوانة نصف قطرها \\(R = 3\\) وارتفاعها \\(h = 5\\) (الصيغة \\(V = \\pi R^2 h\\)؛ أدخل المعامل الصحيح لـ \\(pi\\)، أي \\(R^2 h\\)):",a:45,tol:.001,h:"R² h = 3² · 5 = 9 · 5.",h_ar:"R² h = 3² · 5 = 9 · 5.",sol:"R² h = 3² · 5 = 45.",sol_ar:"R² h = 3² · 5 = 45."},{t:"ord",ti:"Order the Steps: Triple Integration in Spherical Coordinates",ti_ar:"ترتيب الخطوات: التكامل الثلاثي بالإحداثيات الكروية",q:"Order the steps to evaluate a triple integral ∭_E f(x, y, z) dV in spherical coordinates:",q_ar:"رتّب خطوات حساب التكامل الثلاثي ∭_E f(x, y, z) dV بالإحداثيات الكروية:",items:["Identify spherical boundaries such as spheres ρ = a or cones φ = α","Determine angle limits: azimuthal θ ∈ [0, 2π] and colatitude φ ∈ [0, π]","Determine radial limits: ρ from inner radius to outer boundary","Substitute x = ρ sin φ cos θ, y = ρ sin φ sin θ, z = ρ cos φ into f","Insert the volume element dV = ρ² sin φ dρ dφ dθ and integrate iteratively"],items_ar:["تحديد الحدود الكروية مثل الكرات ρ = a أو المخاريط φ = α","تحديد حدود الزوايا: زاوية السمت θ ∈ [0, 2π] وزاوية القطب φ ∈ [0, π]","تحديد حدود نصف القطر: ρ من الحد الداخلي إلى الحد الخارجي","التعويض بـ x = ρ sin φ cos θ، و y = ρ sin φ sin θ، و z = ρ cos φ في دالة f","إدراج عنصر الحجم dV = ρ² sin φ dρ dφ dθ وإجراء التكامل التكراري"],sol:"Spherical coordinates map space via radius ρ, colatitude φ, and azimuth θ with volume metric ρ² sin φ.",sol_ar:"ترسم الإحداثيات الكروية الفضاء بنصف القطر ρ وزاوية القطب φ وزاوية السمت θ مع مقياس الحجم ρ² sin φ."},{t:"cat",ti:"Classify 3D Regions: Cylindrical vs. Spherical Suitability",ti_ar:"تصنيف المناطق ثلاثية الأبعاد: ملاءمة الأسطواني مقابل الكروي",categories:["Cylindrical Coordinates (r, θ, z)","Spherical Coordinates (ρ, φ, θ)"],categories_ar:["الإحداثيات الأسطوانية (r, θ, z)","الإحداثيات الكروية (ρ, φ, θ)"],items:[{s:"Solid bounded by paraboloid z = x² + y² and plane z = 4",cat:0},{s:"Solid sphere x² + y² + z² ≤ 25",cat:1},{s:"Ice cream cone solid between sphere ρ = 3 and cone φ = π/3",cat:1},{s:"Vertical circular cylinder x² + y² ≤ 4 with 0 ≤ z ≤ 6",cat:0},{s:"Integrand with spherical symmetry depending only on (x² + y² + z²)",cat:1}],items_ar:[{s:"مجسم محصور بالسطح المكافئ z = x² + y² والمستوى z = 4",cat:0},{s:"كرة مصمتة x² + y² + z² ≤ 25",cat:1},{s:"مجسم قمع الآيس كريم بين الكرة ρ = 3 والمخروط φ = π/3",cat:1},{s:"أسطوانة دائرية رأسية x² + y² ≤ 4 مع 0 ≤ z ≤ 6",cat:0},{s:"دالة مكاملة ذات تماثل كروي تعتمد فقط على (x² + y² + z²)",cat:1}],sol:"Cylindrical coordinates suit axial symmetry along z; spherical coordinates suit radial symmetry from origin.",sol_ar:"تناسب الإحداثيات الأسطوانية التماثل المحوري حول محور z؛ بينما تناسب الإحداثيات الكروية التماثل الشعاعي حول نقطة الأصل."},{t:"se",ti:"Spot the Error: Spherical Volume Element Jacobian",ti_ar:"اكتشف الخطأ: جاكوبيان عنصر الحجم في الإحداثيات الكروية",q:"A student integrates \\(f(x,y,z) = 1\\) over the unit ball \\(x^2 + y^2 + z^2 \\le 1\\) using spherical coordinates \\((\\rho, \\varphi, \\theta)\\). Which step omits part of the Jacobian?",q_ar:"يكامل طالب \\(f = 1\\) على الكرة الواحدية باستخدام الإحداثيات الكروية \\((\\rho, \\varphi, \\theta)\\). أي خطوة تغفل جزءاً من جاكوبيان التحويل؟",steps:["Set spherical bounds: \\(0 \\le \\rho \\le 1\\), \\(0 \\le \\varphi \\le \\pi\\), \\(0 \\le \\theta \\le 2\\pi\\).","Write volume element as \\(dV = \\rho\\,\\sin\\varphi\\,d\\rho\\,d\\varphi\\,d\\theta\\) instead of \\(\\rho^2\\sin\\varphi\\,d\\rho\\,d\\varphi\\,d\\theta\\).","Integrate \\(\\int_0^1 \\rho\\,d\\rho = \\tfrac{1}{2}\\), \\(\\int_0^\\pi \\sin\\varphi\\,d\\varphi = 2\\), and \\(\\int_0^{2\\pi} d\\theta = 2\\pi\\).","Multiply to get \\(2\\pi\\) instead of \\(\\tfrac{4}{3}\\pi\\)."],steps_ar:["تحديد الحدود الكروية: \\(0 \\le \\rho \\le 1\\) و\\(0 \\le \\varphi \\le \\pi\\) و\\(0 \\le \\theta \\le 2\\pi\\).","كتابة عنصر الحجم \\(dV = \\rho\\sin\\varphi\\,d\\rho\\,d\\varphi\\,d\\theta\\) بدلاً من \\(\\rho^2\\sin\\varphi\\,d\\rho\\,d\\varphi\\,d\\theta\\).","حساب التكاملات المنفصلة.","الحصول على \\(2\\pi\\) بدلاً من حجم الكرة \\(\\tfrac{4}{3}\\pi\\)."],errorStep:2,reasons:["The 3D spherical Jacobian is \\(\\rho^2\\sin\\varphi\\) (giving \\(\\int_0^1 \\rho^2\\,d\\rho = \\frac{1}{3}\\) and volume \\(\\frac{4}{3}\\pi\\)), not \\(\\rho\\sin\\varphi\\).","Azimuthal angle \\(\\varphi\\) should run from \\(0\\) to \\(2\\pi\\).","The cylindrical Jacobian \\(r\\,dr\\,d\\theta\\,dz\\) applies to spherical coordinates unchanged."],reasons_ar:["جاكوبيان الإحداثيات الكروية هو \\(\\rho^2\\sin\\varphi\\) (فيعطي \\(\\int_0^1 \\rho^2\\,d\\rho = 1/3\\) والحجم الصحيح \\(\\frac{4}{3}\\pi\\)).","زاوية الميل \\(\\varphi\\) تمتد من \\(0\\) إلى \\(2\\pi\\).","جاكوبيان الإحداثيات الأسطوانية والكروية متطابقان."],correctReason:0},{t:"ms",ti:"Examiner Mode: Gradient Vector & Hessian Classification (Triple Integrals & Cylindrical/Spherical Coordinates)",ti_ar:"وضع المصحح: متجه التدرج ومصفوفة هيس (التكاملات الثلاثية والإحداثيات الأسطوانية والكروية)",q:"Let \\(f(x, y) = 2x^2 + 4xy + y^2\\). (a) Compute \\(\\nabla f(1, 2)\\). (b) Compute the Hessian determinant \\(D = f_{xx}f_{yy} - (f_{xy})^2\\).",q_ar:"لتكن \\(f(x, y) = 2x^2 + 4xy + y^2\\). (أ) احسب متجه التدرج \\(\\nabla f(1, 2)\\). (ب) احسب محدد هيس \\(D = f_{xx}f_{yy} - (f_{xy})^2\\).",parts:[{label:"Part (a) — Partial Derivatives & Gradient",marks:2,rubric:[{code:"M1",marks:1,text:"\\(f_x = 4x + 4y,\\quad f_y = 4x + 2y\\)."},{code:"A1",marks:1,text:"At \\((1, 2)\\): \\(\\nabla f(1, 2) = \\langle 12, 8 \\rangle\\)."}]},{label:"Part (b) — Second-Derivative Discriminant",marks:2,rubric:[{code:"M1",marks:1,text:"\\(f_{xx} = 4,\\; f_{yy} = 2,\\; f_{xy} = 4\\)."},{code:"A1",marks:1,text:"\\(D = (4)(2) - 4^2 = -8\\)."}]}],parts_ar:[{label:"الجزء (أ) — المشتقات الجزئية ومتجه التدرج",marks:2,rubric:[{code:"M1",marks:1,text:"\\(f_x = 4x + 4y,\\quad f_y = 4x + 2y\\)."},{code:"A1",marks:1,text:"عند \\((1, 2)\\): \\(\\nabla f(1, 2) = \\langle 12, 8 \\rangle\\)."}]},{label:"الجزء (ب) — محدد المشتقات الجزئية الثانية (هيس)",marks:2,rubric:[{code:"M1",marks:1,text:"\\(f_{xx} = 4,\\; f_{yy} = 2,\\; f_{xy} = 4\\)."},{code:"A1",marks:1,text:"\\(D = -8\\)."}]}]},{t:"qc",ti:"Quick Check: Cylindrical vs. Spherical Volume Elements",ti_ar:"فحص سريع: عنصر الحجم في الإحداثيات الأسطوانية والكروية",q:"What is the differential volume element \\(dV\\) in cylindrical coordinates \\((r, \\theta, z)\\)?",q_ar:"ما عنصر الحجم التفاضلي \\(dV\\) في الإحداثيات الأسطوانية \\((r, \\theta, z)\\)؟",o:["\\(r\\,dz\\,dr\\,d\\theta\\)","\\(r^2\\sin\\theta\\,dz\\,dr\\,d\\theta\\)","\\(dz\\,dr\\,d\\theta\\)","\\(\\rho^2\\sin\\varphi\\,d\\rho\\,d\\varphi\\,d\\theta\\)"],o_ar:["\\(r\\,dz\\,dr\\,d\\theta\\)","\\(r^2\\sin\\theta\\,dz\\,dr\\,d\\theta\\)","\\(dz\\,dr\\,d\\theta\\)","\\(\\rho^2\\sin\\varphi\\,d\\rho\\,d\\varphi\\,d\\theta\\)"],a:0,ex:"Cylindrical coordinates combine polar \\((r, \\theta)\\) in the \\(xy\\)-plane with \\(z\\), so \\(dV = dA\\,dz = r\\,dr\\,d\\theta\\,dz\\).",ex_ar:"تدمج الإحداثيات الأسطوانية الإحداثيات القطبية في المستوى \\(xy\\) مع الارتفاع \\(z\\)، فيكون \\(dV = r\\,dz\\,dr\\,d\\theta\\)."}];D["mvc-vector-fields"]=[{t:"sb",ti:"Lab Step Builder: Line Integral of a Vector Field",ti_ar:"بناء خطوات المعمل: التكامل الخطي لمجال متجهي",steps:[{l:"Let \\(mathbf{F} = \\langle y, x \\rangle\\) along \\(mathbf{r}(t) = \\langle t, t^2 \\rangle\\) for \\(t \\in [0, 1]\\). Compute \\(mathbf{r}'(t) = \\langle 1, ?\\rangle\\):",a:"2t",h:"d/dt(t²) = 2t"},{l:"Substitute \\(mathbf{r}(t)\\) into \\(mathbf{F}\\): \\(mathbf{F}(\\mathbf{r}(t)) = \\langle t^2, t \\rangle\\). Compute dot product \\(mathbf{F}\\cdot\\mathbf{r}' = t^2(1) + t(2t) =\\) ? \\(t^2\\):",a:"3",h:"\\(t^2 + 2t^2 = 3t^2\\)"},{l:"Integrate \\(int_0^1 3t^2\\,dt = [t^3]_0^1 =\\)",a:"1",h:"\\(1^3 - 0 = 1\\)"}],steps_ar:[{l:"لتكن \\(mathbf{F} = \\langle y, x \\rangle\\) على طول \\(mathbf{r}(t) = \\langle t, t^2 \\rangle\\) لـ \\(t \\in [0, 1]\\). احسب \\(mathbf{r}'(t) = \\langle 1, ?\\rangle\\):",a:"2t",h:"d/dt(t²) = 2t"},{l:"عوّض \\(mathbf{r}(t)\\) في \\(mathbf{F}\\): \\(mathbf{F}(\\mathbf{r}(t)) = \\langle t^2, t \\rangle\\). احسب الضرب القياسي \\(mathbf{F}\\cdot\\mathbf{r}' = t^2(1) + t(2t) =\\) ؟ \\(t^2\\):",a:"3",h:"\\(t^2 + 2t^2 = 3t^2\\)"},{l:"احسب التكامل \\(int_0^1 3t^2\\,dt = [t^3]_0^1 =\\)",a:"1",h:"\\(1^3 - 0 = 1\\)"}]},{t:"qc",ti:"Lab Check: Fundamental Theorem for Line Integrals",ti_ar:"فحص المعمل: النظرية الأساسية للتكاملات الخطية",q:"If \\(mathbf{F} = \\nabla f\\) is conservative, the work done along any curve \\(C\\) from \\(A\\) to \\(B\\) is:",q_ar:"إذا كان \\(mathbf{F} = \\nabla f\\) مجالاً محافظاً، فإن الشغل المبذول على طول أي منحنى \\(C\\) من \\(A\\) إلى \\(B\\) يساوي:",o:["\\(f(B) - f(A)\\)","\\(f(A) - f(B)\\)","\\(oint_C \\nabla f\\)","\\(0\\) always"],o_ar:["\\(f(B) - f(A)\\)","\\(f(A) - f(B)\\)","\\(oint_C \\nabla f\\)","\\(0\\) دائماً"],a:0,ex:"Line integrals of conservative vector fields are path-independent and depend solely on potential values at endpoints: \\(int_C \\nabla f\\cdot d\\mathbf{r} = f(B) - f(A)\\).",ex_ar:"التكاملات الخطية للمجالات المتجهية المحافظة تكون مستقلة عن المسار وتعتمد فقط على قيم دالة الجهد عند نقطتي البداية والنهاية: \\(int_C \\nabla f\\cdot d\\mathbf{r} = f(B) - f(A)\\)."},{t:"mt",ti:"Matching: Vector Field Concepts",ti_ar:"معمل المطابقة: مفاهيم المجالات المتجهية",p:[{l:"Conservative field F",r:"F = ∇f for some scalar potential f"},{l:"Path independence",r:"∫_C F·dr depends only on endpoints"},{l:"Closed loop line integral ∮_C F·dr",r:"0 for any conservative field"},{l:"2D curl condition",r:"∂Q/∂x = ∂P/∂y on simply connected domain"}],p_ar:[{l:"المجال المحافظ F",r:"F = ∇f لدالة جهد قياسية f"},{l:"الاستقلال عن المسار",r:"∫_C F·dr يعتمد فقط على نقطتي البداية والنهاية"},{l:"تكامل مسار مغلق ∮_C F·dr",r:"0 لأي مجال محافظ"},{l:"شرط الالتفاف ثنائي الأبعاد",r:"∂Q/∂x = ∂P/∂y على نطاق مترابط بسيط"}]},{t:"num",ti:"Work Done by Conservative Field",ti_ar:"الشغل المبذول بواسطة مجال محافظ",q:"A conservative force field \\(mathbf{F} = \\nabla f\\) has potential \\(f(x, y) = x^2 y + 3y^2\\). Find the work done \\(int_C \\mathbf{F}\\cdot d\\mathbf{r}\\) along any smooth curve from \\(A(1, 1)\\) to \\(B(2, 3)\\):",q_ar:"مجال قوة محافظ \\(mathbf{F} = \\nabla f\\) له دالة جهد \\(f(x, y) = x^2 y + 3y^2\\). أوجد الشغل المبذول \\(int_C \\mathbf{F}\\cdot d\\mathbf{r}\\) على طول أي منحنى أملس من \\(A(1, 1)\\) إلى \\(B(2, 3)\\):",a:35,tol:.001,h:"Work = f(B) - f(A). Compute f(2, 3) and f(1, 1).",h_ar:"الشغل = f(B) - f(A). احسب f(2, 3) و f(1, 1).",sol:"f(2, 3) = 2²(3) + 3(3²) = 12 + 27 = 39. f(1, 1) = 1(1) + 3(1) = 4. Work = 39 - 4 = 35.",sol_ar:"f(2, 3) = 2²(3) + 3(3²) = 12 + 27 = 39. f(1, 1) = 1(1) + 3(1) = 4. الشغل = 39 - 4 = 35."},{t:"ord",ti:"Order the Steps: Find Potential Function f(x, y)",ti_ar:"ترتيب الخطوات: إيجاد دالة الجهد f(x, y)",q:"Order the steps to find a potential function f(x, y) for a conservative field F = ⟨P, Q⟩:",q_ar:"رتّب خطوات إيجاد دالة الجهد f(x, y) لمجال متجهي محافظ F = ⟨P, Q⟩:",items:["Check that ∂P/∂y = ∂Q/∂x throughout an open simply connected domain","Integrate f_x = P with respect to x, adding an unknown function of y: f(x, y) = ∫ P dx + g(y)","Differentiate this expression for f(x, y) with respect to y: ∂f/∂y = ∂/∂y[∫ P dx] + g'(y)","Equate ∂f/∂y with Q(x, y) to isolate and solve for g'(y)","Integrate g'(y) to find g(y) and write down the complete potential function f(x, y)"],items_ar:["التحقق من أن ∂P/∂y = ∂Q/∂x في نطاق مفتوح ومترابط بسيط","مكاملة f_x = P بالنسبة إلى x مع إضافة دالة مجهولة لـ y: f(x, y) = ∫ P dx + g(y)","اشتقاق هذا التعبير لـ f(x, y) بالنسبة إلى y: ∂f/∂y = ∂/∂y[∫ P dx] + g'(y)","مساواة ∂f/∂y مع Q(x, y) لعزل g'(y) وحلها","مكاملة g'(y) لإيجاد g(y) وكتابة دالة الجهد الكاملة f(x, y)"],sol:"Potential functions are found by integrating one component and differentiating to solve for the remaining single-variable function.",sol_ar:"يتم إيجاد دوال الجهد عبر مكاملة إحدى المركبات واشتقاقها لحل دالة المتغير المتبقي."},{t:"cat",ti:"Classify Vector Fields: Conservative vs. Non-Conservative",ti_ar:"تصنيف المجالات المتجهية: محافظ مقابل غير محافظ",categories:["Conservative Vector Field","Non-Conservative Vector Field"],categories_ar:["مجال متجهي محافظ","مجال متجهي غير محافظ"],items:[{s:"F = ∇f for a smooth scalar potential f",cat:0},{s:"Line integral around every simple closed curve is zero: ∮_C F · dr = 0",cat:0},{s:"Line integral value depends on the path taken between fixed endpoints",cat:1},{s:"Curl of F is non-zero (∇ × F ≠ 0)",cat:1},{s:"F(x, y) = ⟨2xy, x²⟩ on all of ℝ²",cat:0}],items_ar:[{s:"F = ∇f لدالة جهد قياسية ملساء f",cat:0},{s:"التكامل الخطي حول أي مسار مغلق بسيط يساوي صفراً: ∮_C F · dr = 0",cat:0},{s:"قيمة التكامل الخطي تعتمد على المسار المتبع بين نقطتي البداية والنهاية",cat:1},{s:"التفاف F لا يساوي صفراً (∇ × F ≠ 0)",cat:1},{s:"F(x, y) = ⟨2xy, x²⟩ على كامل ℝ²",cat:0}],sol:"Conservative vector fields have path-independent integrals, vanish around closed loops, and have zero curl.",sol_ar:"المجالات المتجهية المحافظة تتميز باستقلال تكاملاتها عن المسار، وانعدام دورانها، وانعدام تكاملها على المسارات المغلقة."},{t:"se",ti:"Spot the Error: Path Independence on a Non-Conservative Vector Field",ti_ar:"اكتشف الخطأ: افتراض استقلال المسار لحقل متجهي غير محافظ",q:"A student evaluates \\(\\int_C \\mathbf{F}\\cdot d\\mathbf{r}\\) for \\(\\mathbf{F}(x, y) = \\langle -y, x \\rangle\\) around the unit circle \\(C\\). Which step is invalid?",q_ar:"يحسب طالب التكامل الخطي \\(\\int_C \\mathbf{F}\\cdot d\\mathbf{r}\\) للحقل \\(\\mathbf{F}(x, y) = \\langle -y, x \\rangle\\) حول دائرة الوحدة المغلقة \\(C\\). أي خطوة خاطئة؟",steps:["Identify \\(P(x, y) = -y\\) and \\(Q(x, y) = x\\).","Note that \\(C\\) is a closed curve starting and ending at \\((1, 0)\\).","Claim every line integral around a closed curve is automatically \\(0\\) without checking \\(Q_x = P_y\\).","Report \\(\\oint_C \\mathbf{F}\\cdot d\\mathbf{r} = 0\\)."],steps_ar:["تحديد المركبتين \\(P = -y\\) و\\(Q = x\\).","ملاحظة أن المنحنى \\(C\\) مغلق يبدأ وينتهي عند \\((1, 0)\\).","الادعاء بأن التكامل الخطي حول أي مسار مغلق يساوي \\(0\\) دائماً دون فحص \\(Q_x = P_y\\).","كتابة الناتج \\(0\\)."],errorStep:3,reasons:["Closed-loop circulation vanishes only for conservative fields; here \\(Q_x - P_y = 1 - (-1) = 2 \\neq 0\\), so \\(\\oint_C \\mathbf{F}\\cdot d\\mathbf{r} = 2\\pi\\).","Unit circle parameterization requires clockwise orientation.","Line integrals are only defined for scalar functions."],reasons_ar:["ينعدم التكامل المغلق فقط للحقول المحافظة؛ وهنا \\(Q_x - P_y = 2 \\neq 0\\) فيكون التكامل \\(2\\pi\\) وليس صفراً.","يجب تمثيل دائرة الوحدة مع عقارب الساعة.","التكامل الخطي معرف للدوال القياسية فقط."],correctReason:0},{t:"ms",ti:"Examiner Mode: Gradient Vector & Hessian Classification (Vector Fields & Line Integrals)",ti_ar:"وضع المصحح: متجه التدرج ومصفوفة هيس (الحقول المتجهة والتكاملات الخطية والحقول المحافظة)",q:"Let \\(f(x, y) = 3x^2 + 1xy + y^2\\). (a) Compute \\(\\nabla f(1, 2)\\). (b) Compute the Hessian determinant \\(D = f_{xx}f_{yy} - (f_{xy})^2\\).",q_ar:"لتكن \\(f(x, y) = 3x^2 + 1xy + y^2\\). (أ) احسب متجه التدرج \\(\\nabla f(1, 2)\\). (ب) احسب محدد هيس \\(D = f_{xx}f_{yy} - (f_{xy})^2\\).",parts:[{label:"Part (a) — Partial Derivatives & Gradient",marks:2,rubric:[{code:"M1",marks:1,text:"\\(f_x = 6x + 1y,\\quad f_y = 1x + 2y\\)."},{code:"A1",marks:1,text:"At \\((1, 2)\\): \\(\\nabla f(1, 2) = \\langle 8, 5 \\rangle\\)."}]},{label:"Part (b) — Second-Derivative Discriminant",marks:2,rubric:[{code:"M1",marks:1,text:"\\(f_{xx} = 6,\\; f_{yy} = 2,\\; f_{xy} = 1\\)."},{code:"A1",marks:1,text:"\\(D = (6)(2) - 1^2 = 11\\)."}]}],parts_ar:[{label:"الجزء (أ) — المشتقات الجزئية ومتجه التدرج",marks:2,rubric:[{code:"M1",marks:1,text:"\\(f_x = 6x + 1y,\\quad f_y = 1x + 2y\\)."},{code:"A1",marks:1,text:"عند \\((1, 2)\\): \\(\\nabla f(1, 2) = \\langle 8, 5 \\rangle\\)."}]},{label:"الجزء (ب) — محدد المشتقات الجزئية الثانية (هيس)",marks:2,rubric:[{code:"M1",marks:1,text:"\\(f_{xx} = 6,\\; f_{yy} = 2,\\; f_{xy} = 1\\)."},{code:"A1",marks:1,text:"\\(D = 11\\)."}]}]},{t:"qc",ti:"Quick Check: Conservative Vector Field Criterion on ℝ²",ti_ar:"فحص سريع: شرط الحقل المتجهي المحافظ في ℝ²",q:"On a simply connected domain in \\(\\mathbb{R}^2\\), smooth vector field \\(\\mathbf{F} = \\langle P(x,y), Q(x,y) \\rangle\\) is conservative (\\(\\mathbf{F} = \\nabla f\\)) if and only if:",q_ar:"على منطقة متصلة ببساطة في \\(\\mathbb{R}^2\\)، يكون الحقل المتجهي الأملس \\(\\mathbf{F} = \\langle P, Q \\rangle\\) محافظاً إذا وفقط إذا:",o:["\\(\\dfrac{\\partial Q}{\\partial x} = \\dfrac{\\partial P}{\\partial y}\\)","\\(\\dfrac{\\partial P}{\\partial x} + \\dfrac{\\partial Q}{\\partial y} = 0\\)","\\(P(x,y) = Q(x,y)\\)","\\(\\mathbf{F}(0,0) = \\mathbf{0}\\)"],o_ar:["\\(\\dfrac{\\partial Q}{\\partial x} = \\dfrac{\\partial P}{\\partial y}\\)","\\(\\dfrac{\\partial P}{\\partial x} + \\dfrac{\\partial Q}{\\partial y} = 0\\)","\\(P(x,y) = Q(x,y)\\)","\\(\\mathbf{F}(0,0) = \\mathbf{0}\\)"],a:0,ex:"If \\(P = f_x\\) and \\(Q = f_y\\), Clairaut’s theorem gives \\(Q_x = f_{yx} = f_{xy} = P_y\\); simple connectedness makes this sufficient.",ex_ar:"إذا كان \\(P = f_x\\) و\\(Q = f_y\\) فإن \\(Q_x = P_y\\)، وعلى منطقة متصلة ببساطة يكون هذا الشرط كافياً ولازماً."}];D["mvc-greens-theorem"]=[{t:"sb",ti:"Lab Step Builder: Green's Theorem Application",ti_ar:"بناء خطوات المعمل: تطبيق مبرهنة غرين",steps:[{l:"Green's theorem states \\(oint_C (P,dx + Q,dy) = iint_D left(\\dfrac{partial Q}{partial x} - \\dfrac{partial P}{partial y}\right)dA\\). For \\(P = -y^3\\), \\(Q = x^3\\), \\(\\dfrac{partial Q}{partial x} =\\)",a:"3x^2",h:"d/dx(x³) = 3x²"},{l:"\\(\\dfrac{partial P}{partial y} =\\)",a:"-3y^2",h:"d/dy(-y³) = -3y²"},{l:"The integrand \\(\\dfrac{partial Q}{partial x} - \\dfrac{partial P}{partial y} = 3(x^2 + y^2)\\). Across circle \\(x^2+y^2le 1\\), in polar this is \\(3r^2cdot r = 3r^3\\). Integrate \\(int_0^{2pi}int_0^1 3r^3,dr,d\\theta = 2pi \\times [\\frac{3}{4}r^4]_0^1 =\\) (enter fraction like 3/2pi as 1.5pi or 3pi/2):",a:"3pi/2",h:"\\(2pi \\times 3/4 = 3pi/2\\)"}],steps_ar:[{l:"تنص مبرهنة غرين على أن \\(oint_C (P,dx + Q,dy) = iint_D left(\\dfrac{partial Q}{partial x} - \\dfrac{partial P}{partial y}\right)dA\\). إذا كانت \\(P = -y^3\\) و \\(Q = x^3\\)، فإن \\(\\dfrac{partial Q}{partial x} =\\)",a:"3x^2",h:"d/dx(x³) = 3x²"},{l:"\\(\\dfrac{partial P}{partial y} =\\)",a:"-3y^2",h:"d/dy(-y³) = -3y²"},{l:"دالة المكاملة \\(\\dfrac{partial Q}{partial x} - \\dfrac{partial P}{partial y} = 3(x^2 + y^2)\\). عبر القرص \\(x^2+y^2le 1\\)، بالصورة القطبية تصبح \\(3r^2cdot r = 3r^3\\). احسب \\(int_0^{2pi}int_0^1 3r^3,dr,d\\theta = 2pi \\times [\\frac{3}{4}r^4]_0^1 =\\) (أدخل الكسر مثل 3/2pi بصورة 1.5pi أو 3pi/2):",a:"3pi/2",h:"\\(2pi \\times 3/4 = 3pi/2\\)"}]},{t:"tf",ti:"Reasoning Lab: Green's Theorem Hypotheses",ti_ar:"معمل الاستنتاج: فرضيات مبرهنة غرين",items:[{s:"Green's theorem requires the boundary curve C to be positively oriented (counterclockwise).",a:true,ex:"Counterclockwise orientation ensures the interior domain D lies to the left of the curve."},{s:"Green's theorem can be used to compute the area of a region using \\(\\text{Area} = \\frac{1}{2}oint_C (x,dy - y,dx)\\).",a:true,ex:"Here \\(partial Q/partial x - partial P/partial y = 1/2(1 - (-1)) = 1\\), which integrates to Area."}],items_ar:[{s:"تتطلب مبرهنة غرين أن يكون منحنى الحدود C موجّهًا في الاتجاه الموجب (عكس اتجاه عقارب الساعة).",ex:"يضمن الاتجاه المعاكس لعقارب الساعة أن تكون المنطقة الداخلية D واقعة على يسار المنحنى أثناء السير عليه.",a:true},{s:"يمكن استخدام مبرهنة غرين لحساب مساحة منطقة ما باستخدام الصيغة \\(\\text{Area} = \\frac{1}{2}oint_C (x,dy - y,dx)\\).",ex:"هنا \\(partial Q/partial x - partial P/partial y = 1/2(1 - (-1)) = 1\\)، والتي عند مكاملتها تعطي المساحة بالضبط.",a:true}]},{t:"qc",ti:"Quick Check: Green's Theorem Boundary Orientation",ti_ar:"فحص سريع: اتجاه حدود مبرهنة غرين",q:"If a closed curve \\(C\\) is traversed in the clockwise direction, how does the line integral \\(oint_C P,dx + Q,dy\\) relate to the double integral over the interior \\(D\\)?",q_ar:"إذا تم السير على منحنى مغلق \\(C\\) في اتجاه عقارب الساعة، فكيف يرتبط التكامل الخطي \\(oint_C P,dx + Q,dy\\) بالتكامل الثنائي على المنطقة الداخلية \\(D\\)؟",o:["\\(-iint_D (Q_x - P_y),dA\\)","\\(iint_D (Q_x - P_y),dA\\)","\\(0\\)","\\(iint_D (P_x + Q_y),dA\\)"],o_ar:["\\(-iint_D (Q_x - P_y),dA\\)","\\(iint_D (Q_x - P_y),dA\\)","\\(0\\)","\\(iint_D (P_x + Q_y),dA\\)"],a:0,ex:"Clockwise traversal is negative orientation (-C), reversing the sign of the line integral: \\(oint_{-C} = -oint_C = -iint_D (Q_x - P_y),dA\\).",ex_ar:"السير في اتجاه عقارب الساعة يمثل توجيهاً سالباً (-C)، مما يعكس إشارة التكامل الخطي: \\(oint_{-C} = -oint_C = -iint_D (Q_x - P_y),dA\\)."},{t:"num",ti:"Evaluate Circulation via Green's Theorem",ti_ar:"حساب الدوران باستخدام مبرهنة غرين",q:"Use Green's theorem to evaluate \\(oint_C (3y,dx + 7x,dy)\\) where \\(C\\) is the positively oriented boundary of a circle of radius 2. (Enter the integer coefficient of \\(pi\\) in the answer \\(kpi\\)):",q_ar:"استخدم مبرهنة غرين لحساب \\(oint_C (3y,dx + 7x,dy)\\) حيث \\(C\\) هو المسار الموجه موجباً لدائرة نصف قطرها 2. (أدخل المعامل الصحيح لـ \\(pi\\) في الإجابة \\(kpi\\)):",a:16,tol:.001,h:"Q_x - P_y = 7 - 3 = 4. Double integral = 4 · Area = 4 · (π · 2²) = 16π.",h_ar:"Q_x - P_y = 7 - 3 = 4. التكامل الثنائي = 4 · المساحة = 4 · (π · 2²) = 16π.",sol:"Q_x - P_y = 4. Line integral = 4 · Area(circle) = 4 · (4π) = 16π. The integer coefficient is 16.",sol_ar:"Q_x - P_y = 4. التكامل الخطي = 4 · (4π) = 16π. المعامل الصحيح هو 16."},{t:"ord",ti:"Order the Steps: Applying Green's Theorem",ti_ar:"ترتيب الخطوات: تطبيق مبرهنة غرين",q:"Order the steps to transform and evaluate a closed planar line integral using Green's Theorem:",q_ar:"رتّب خطوات تحويل وحساب التكامل الخطي المستوي المغلق باستخدام مبرهنة غرين:",items:["Verify that curve C is a closed, simple, positively oriented boundary curve","Identify P(x, y) as the dx coefficient and Q(x, y) as the dy coefficient","Compute partial derivatives ∂Q/∂x and ∂P/∂y","Form the 2D curl difference: (∂Q/∂x - ∂P/∂y)","Set up and evaluate the double integral ∬_D (∂Q/∂x - ∂P/∂y) dA over region D"],items_ar:["التحقق من أن المنحنى C مغلق وبسيط وموجه إيجابياً كحدود لمنطقة","تحديد P(x, y) كمعامل لـ dx و Q(x, y) كمعامل لـ dy","حساب المشتقات الجزئية ∂Q/∂x و ∂P/∂y","تكوين فرق الالتفاف ثنائي الأبعاد: (∂Q/∂x - ∂P/∂y)","إعداد وحساب التكامل الثنائي ∬_D (∂Q/∂x - ∂P/∂y) dA على المنطقة D"],sol:"Green's theorem converts a closed line integral into a double integral of 2D curl over the interior.",sol_ar:"تحول مبرهنة غرين التكامل الخطي المغلق إلى تكامل ثنائي لالتفاف المجال في المستوى ثنائي الأبعاد."},{t:"cat",ti:"Classify Boundary Orientations for Planar Regions",ti_ar:"تصنيف اتجاهات الحدود للمناطق المستوية",categories:["Positive Orientation (Counter-Clockwise Outer Loop)","Negative Orientation (Clockwise Outer Loop)"],categories_ar:["توجيه موجب (عكس اتجاه عقارب الساعة للمسار الخارجي)","توجيه سالب (مع اتجاه عقارب الساعة للمسار الخارجي)"],items:[{s:"Walking along curve keeping the interior domain to the left",cat:0},{s:"Walking along curve keeping the interior domain to the right",cat:1},{s:"Counter-clockwise traversal around circle x² + y² = 1",cat:0},{s:"Clockwise traversal around the boundary of a triangle",cat:1},{s:"Standard orientation yielding ∮_C F·dr = +∬_D (Q_x - P_y) dA",cat:0}],items_ar:[{s:"السير على المنحنى مع إبقاء المنطقة الداخلية على اليسار",cat:0},{s:"السير على المنحنى مع إبقاء المنطقة الداخلية على اليمين",cat:1},{s:"الدوران عكس اتجاه عقارب الساعة حول الدائرة x² + y² = 1",cat:0},{s:"الدوران مع اتجاه عقارب الساعة حول محيط مثلث",cat:1},{s:"التوجيه القياسي الذي يعطي ∮_C F·dr = +∬_D (Q_x - P_y) dA",cat:0}],sol:"Positive orientation keeps the interior on the left and corresponds to counter-clockwise outer loops.",sol_ar:"يبقي التوجيه الموجب المنطقة الداخلية على اليسار ويتطابق مع الدوران عكس عقارب الساعة للمسارات الخارجية."},{t:"se",ti:"Spot the Error: Sign & Orientation in Green’s Theorem",ti_ar:"اكتشف الخطأ: الإشارة واتجاه الحدود في مبرهنة غرين",q:"A student uses Green’s Theorem to evaluate \\(\\oint_C (y\\,dx + 3x\\,dy)\\) where \\(C\\) is the CLOCKWISE circle \\(x^2 + y^2 = 4\\). Which step mishandles orientation?",q_ar:"يطبق طالب مبرهنة غرين لحساب \\(\\oint_C (y\\,dx + 3x\\,dy)\\) حيث \\(C\\) الدائرة \\(x^2 + y^2 = 4\\) باتجاه عقارب الساعة. أي خطوة أخطأت في الاتجاه؟",steps:["Identify \\(P = y\\) and \\(Q = 3x\\), so \\(Q_x - P_y = 3 - 1 = 2\\).","Write \\(\\oint_C (P\\,dx + Q\\,dy) = +\\iint_D 2\\,dA\\) without negating for clockwise orientation.","Compute \\(2 \\cdot \\text{Area}(D) = 2(\\pi \\cdot 2^2) = 8\\pi\\).","Conclude the clockwise circulation is \\(+8\\pi\\)."],steps_ar:["تحديد \\(P = y\\) و\\(Q = 3x\\)، ومنه \\(Q_x - P_y = 3 - 1 = 2\\).","كتابة \\(+\\iint_D 2\\,dA\\) دون عكس الإشارة لأن المسار مع عقارب الساعة.","حساب \\(2(4\\pi) = 8\\pi\\).","استنتاج أن التكامل باتجاه عقارب الساعة يساوي \\(+8\\pi\\)."],errorStep:2,reasons:["Green’s Theorem assumes positive (counter-clockwise) boundary orientation; a clockwise curve reverses the sign to \\(-\\iint_D (Q_x - P_y)\\,dA = -8\\pi\\).","Green’s Theorem integrand is \\(P_x + Q_y\\) rather than \\(Q_x - P_y\\).","Area of \\(x^2 + y^2 \\le 4\\) is \\(2\\pi\\), not \\(4\\pi\\)."],reasons_ar:["تفترض مبرهنة غرين الاتجاه الموجب (عكس عقارب الساعة)؛ لذا الاتجاه مع عقارب الساعة يعكس الإشارة إلى \\(-8\\pi\\).","مُكامَل مبرهنة غرين هو \\(P_x + Q_y\\).","مساحة القرص \\(x^2 + y^2 \\le 4\\) تساوي \\(2\\pi\\)."],correctReason:0},{t:"ms",ti:"Examiner Mode: Gradient Vector & Hessian Classification (Green's Theorem)",ti_ar:"وضع المصحح: متجه التدرج ومصفوفة هيس (نظرية غرين (Green's Theorem) في المستوى)",q:"Let \\(f(x, y) = 4x^2 + 2xy + y^2\\). (a) Compute \\(\\nabla f(1, 2)\\). (b) Compute the Hessian determinant \\(D = f_{xx}f_{yy} - (f_{xy})^2\\).",q_ar:"لتكن \\(f(x, y) = 4x^2 + 2xy + y^2\\). (أ) احسب متجه التدرج \\(\\nabla f(1, 2)\\). (ب) احسب محدد هيس \\(D = f_{xx}f_{yy} - (f_{xy})^2\\).",parts:[{label:"Part (a) — Partial Derivatives & Gradient",marks:2,rubric:[{code:"M1",marks:1,text:"\\(f_x = 8x + 2y,\\quad f_y = 2x + 2y\\)."},{code:"A1",marks:1,text:"At \\((1, 2)\\): \\(\\nabla f(1, 2) = \\langle 12, 6 \\rangle\\)."}]},{label:"Part (b) — Second-Derivative Discriminant",marks:2,rubric:[{code:"M1",marks:1,text:"\\(f_{xx} = 8,\\; f_{yy} = 2,\\; f_{xy} = 2\\)."},{code:"A1",marks:1,text:"\\(D = (8)(2) - 2^2 = 12\\)."}]}],parts_ar:[{label:"الجزء (أ) — المشتقات الجزئية ومتجه التدرج",marks:2,rubric:[{code:"M1",marks:1,text:"\\(f_x = 8x + 2y,\\quad f_y = 2x + 2y\\)."},{code:"A1",marks:1,text:"عند \\((1, 2)\\): \\(\\nabla f(1, 2) = \\langle 12, 6 \\rangle\\)."}]},{label:"الجزء (ب) — محدد المشتقات الجزئية الثانية (هيس)",marks:2,rubric:[{code:"M1",marks:1,text:"\\(f_{xx} = 8,\\; f_{yy} = 2,\\; f_{xy} = 2\\)."},{code:"A1",marks:1,text:"\\(D = 12\\)."}]}]},{t:"mt",ti:"Matching: Multivariable & Vector Integral Theorems (Green's Theorem)",ti_ar:"مطابقة: نظريات التفاضل والتكامل المتجهي (نظرية غرين (Green's Theorem) في المستوى)",p:[{l:"Directional derivative \\(D_{\\mathbf{u}} f\\)",r:"\\(\\nabla f \\cdot \\mathbf{u}\\) (unit \\(\\mathbf{u}\\))"},{l:"Green's Theorem (circulation)",r:"\\(\\oint_C \\mathbf{F}\\cdot d\\mathbf{r} = \\iint_D (Q_x - P_y)\\,dA\\)"},{l:"Spherical volume element \\(dV\\)",r:"\\(\\rho^2 \\sin\\varphi\\,d\\rho\\,d\\varphi\\,d\\theta\\)"},{l:"Divergence Theorem (outward flux)",r:"\\(\\iint_{\\partial E} \\mathbf{F}\\cdot \\mathbf{n}\\,dS = \\iiint_E (\\nabla \\cdot \\mathbf{F})\\,dV\\)"}],p_ar:[{l:"المشتقة الاتجاهية \\(D_{\\mathbf{u}} f\\)",r:"\\(\\nabla f \\cdot \\mathbf{u}\\) (لمتجه وحدة \\(\\mathbf{u}\\))"},{l:"مبرهنة غرين للدوران",r:"\\(\\oint_C \\mathbf{F}\\cdot d\\mathbf{r} = \\iint_D (Q_x - P_y)\\,dA\\)"},{l:"عنصر الحجم في الإحداثيات الكروية \\(dV\\)",r:"\\(\\rho^2 \\sin\\varphi\\,d\\rho\\,d\\varphi\\,d\\theta\\)"},{l:"مبرهنة التباعد للتدفق السطحي",r:"\\(\\iint_{\\partial E} \\mathbf{F}\\cdot \\mathbf{n}\\,dS = \\iiint_E (\\nabla \\cdot \\mathbf{F})\\,dV\\)"}]}];D["mvc-surface-divergence-stokes"]=[{t:"mt",ti:"Matching Lab: Fundamental Theorems of Vector Calculus",ti_ar:"معمل المطابقة: النظريات الأساسية لحساب التفاضل والتكامل المتجهي",p:[{l:"Green's Theorem",r:"∮_C F·dr = ∬_D (Q_x − P_y) dA"},{l:"Stokes' Theorem",r:"∮_C F·dr = ∬_S (∇ × F) · dS"},{l:"Divergence Theorem",r:"∬_S F·dS = ∭_E (∇ · F) dV"},{l:"Curl of gradient ∇ × (∇f)",r:"0 (always identically zero)"}],p_ar:[{l:"مبرهنة غرين (Green)",r:"∮_C F·dr = ∬_D (Q_x − P_y) dA"},{l:"مبرهنة ستوكس (Stokes)",r:"∮_C F·dr = ∬_S (∇ × F) · dS"},{l:"مبرهنة التباعد (Divergence)",r:"∬_S F·dS = ∭_E (∇ · F) dV"},{l:"التفاف التدرج ∇ × (∇f)",r:"0 (دائماً يساوي صفراً)"}]},{t:"qc",ti:"Lab Check: Divergence Theorem Physical Meaning",ti_ar:"فحص المعمل: المعنى الفيزيائي لمبرهنة التباعد",q:"If \\(iint_S \\mathbf{F}\\cdot d\\mathbf{S} > 0\\) across a closed outward-oriented boundary surface, the enclosed region contains:",q_ar:"إذا كان \\(iint_S \\mathbf{F}\\cdot d\\mathbf{S} > 0\\) عبر سطح حدودي مغلق وموجه نحو الخارج، فإن المنطقة المحصورة تحتوي على:",o:["A net source of flux (divergence > 0)","A net sink of flux (divergence < 0)","No fluid generation or absorption","A pure rotational vortex"],o_ar:["مصدر صافٍ للتدفق (التباعد > 0)","مصب صافٍ للتدفق (التباعد < 0)","انعدام توليد أو امتصاص المائع","دوامة دورانية نقية"],a:0,ex:"By the Divergence Theorem, total outward flux equals the volume integral of divergence. A positive net flux indicates net generation of fluid (a source).",ex_ar:"وفقاً لمبرهنة التباعد، يساوي إجمالي التدفق نحو الخارج تكامل التباعد على الحجم. ويشير التدفق الإيجابي الصافي إلى توليد مائع (مصدر صافٍ)."},{t:"sb",ti:"Lab Step Builder: Divergence of a 3D Vector Field",ti_ar:"بناء خطوات المعمل: تباعد مجال متجهي ثلاثي الأبعاد",steps:[{l:"For \\(mathbf{F} = \\langle x^2 y, \\; 2yz, \\; 3z^2 x \\rangle\\), compute \\(\\dfrac{\\partial P}{\\partial x} =\\) ? \\(xy\\):",a:"2",h:"d/dx(x² y) = 2xy"},{l:"Compute \\(\\dfrac{\\partial Q}{\\partial y} =\\) ? \\(z\\):",a:"2",h:"d/dy(2yz) = 2z"},{l:"Compute \\(\\dfrac{\\partial R}{\\partial z} =\\) ? \\(zx\\):",a:"6",h:"d/dz(3z² x) = 6zx"}],steps_ar:[{l:"للمجال \\(mathbf{F} = \\langle x^2 y, \\; 2yz, \\; 3z^2 x \\rangle\\)، احسب \\(\\dfrac{\\partial P}{\\partial x} =\\) ؟ \\(xy\\):",a:"2",h:"d/dx(x² y) = 2xy"},{l:"احسب \\(\\dfrac{\\partial Q}{\\partial y} =\\) ؟ \\(z\\):",a:"2",h:"d/dy(2yz) = 2z"},{l:"احسب \\(\\dfrac{\\partial R}{\\partial z} =\\) ؟ \\(zx\\):",a:"6",h:"d/dz(3z² x) = 6zx"}]},{t:"num",ti:"Calculate Divergence at a Given Point",ti_ar:"حساب التباعد عند نقطة معينة",q:"Compute the divergence \\(\nabla \\cdot \\mathbf{F}\\) at the point \\((1, 2, 3)\\) for the vector field \\(mathbf{F} = \\langle 2x^2 y, \\; 3y^2 z, \\; 4z^2 x \\rangle\\):",q_ar:"احسب قيمة التباعد \\(\nabla \\cdot \\mathbf{F}\\) عند النقطة \\((1, 2, 3)\\) للمجال المتجهي \\(mathbf{F} = \\langle 2x^2 y, \\; 3y^2 z, \\; 4z^2 x \\rangle\\):",a:68,tol:.001,h:"div F = 4xy + 6yz + 8zx. Evaluate at (1, 2, 3): 4(1)(2) + 6(2)(3) + 8(3)(1) = 8 + 36 + 24.",h_ar:"div F = 4xy + 6yz + 8zx. احسب القيمة عند (1, 2, 3): 4(1)(2) + 6(2)(3) + 8(3)(1) = 8 + 36 + 24.",sol:"div F = 4xy + 6yz + 8zx. At (1, 2, 3): 8 + 36 + 24 = 68.",sol_ar:"div F = 4xy + 6yz + 8zx. عند (1, 2, 3): 8 + 36 + 24 = 68."},{t:"ord",ti:"Order the Steps: Applying Stokes' Theorem",ti_ar:"ترتيب الخطوات: تطبيق مبرهنة ستوكس",q:"Order the steps to evaluate a line integral ∮_C F · dr around boundary loop C using Stokes' Theorem:",q_ar:"رتّب خطوات حساب التكامل الخطي ∮_C F · dr حول مسار حدودي مغلق C باستخدام مبرهنة ستوكس:",items:["Verify that curve C is a closed, oriented boundary curve of surface S","Compute the curl vector field ∇ × F = ⟨R_y - Q_z, P_z - R_x, Q_x - P_y⟩","Choose a simple oriented surface S spanning boundary curve C (such as a planar disk or paraboloid)","Determine the outward unit normal vector n conforming to C via the right-hand rule","Compute the surface integral ∬_S (∇ × F) · dS = ∬_D (∇ × F) · n dA"],items_ar:["التحقق من أن المنحنى C مغلق وموجّه ويمثل حدوداً لسطح S","حساب مجال الالتفاف المتجهي ∇ × F = ⟨R_y - Q_z, P_z - R_x, Q_x - P_y⟩","اختيار سطح موجّه بسيط S يحده المنحنى C (مثل قرص مستوٍ أو سطح مكافئ)","تحديد متجه الوحدة العمودي الخارجي n المتوافق مع اتجاه C وفق قاعدة اليد اليمنى","حساب التكامل السطحي ∬_S (∇ × F) · dS = ∬_D (∇ × F) · n dA"],sol:"Stokes' theorem equates boundary circulation to the surface flux of curl.",sol_ar:"تربط مبرهنة ستوكس الدوران حول الحدود بتدفق الالتفاف عبر السطح المحاط بتلك الحدود."},{t:"cat",ti:"Classify Theorems by Integral Relationship Type",ti_ar:"تصنيف النظريات حسب نوع العلاقة التكاملية",categories:["Boundary Line Integral to Surface/Region Integral","Closed Surface Integral to Volume Integral"],categories_ar:["من تكامل خطي على الحدود إلى تكامل سطحي/منطقة","من تكامل سطحي مغلق إلى تكامل حجمي"],items:[{s:"Green's Theorem: ∮_C F·dr = ∬_D (Q_x - P_y) dA",cat:0},{s:"Stokes' Theorem: ∮_C F·dr = ∬_S (∇ × F) · dS",cat:0},{s:"Divergence Theorem: ∬_S F·dS = ∭_E (∇ · F) dV",cat:1},{s:"Gauss's Law equating closed surface flux to enclosed charge volume",cat:1},{s:"Circulation of curl over an open capped surface",cat:0}],items_ar:[{s:"مبرهنة غرين: ∮_C F·dr = ∬_D (Q_x - P_y) dA",cat:0},{s:"مبرهنة ستوكس: ∮_C F·dr = ∬_S (∇ × F) · dS",cat:0},{s:"مبرهنة التباعد: ∬_S F·dS = ∭_E (∇ · F) dV",cat:1},{s:"قانون غاوس الذي يساوي تدفق السطح المغلق بحجم الشحنة المحصورة",cat:1},{s:"دوران الالتفاف عبر سطح مفتوح محدد بحدود",cat:0}],sol:"Green's and Stokes' theorems connect boundary loops (1D) to surfaces (2D); Divergence theorem connects closed boundaries (2D) to volumes (3D).",sol_ar:"تربط مبرهنتا غرين وستوكس المسارات الحدودية (1D) بالسطوح (2D)؛ بينما تربط مبرهنة التباعد السطوح المغلقة (2D) بالأحجام (3D)."},{t:"se",ti:"Spot the Error: Applying the Divergence Theorem to an Open Surface",ti_ar:"اكتشف الخطأ: تطبيق مبرهنة التباعد على سطح مفتوح غير مغلق",q:"A student computes upward flux \\(\\iint_S \\mathbf{F}\\cdot d\\mathbf{S}\\) of \\(\\mathbf{F} = \\langle x, y, z \\rangle\\) through the OPEN upper hemisphere \\(z = \\sqrt{1 - x^2 - y^2}\\) (without the base disk \\(z = 0\\)). Which step is invalid?",q_ar:"يحسب طالب التدفق العلوي \\(\\iint_S \\mathbf{F}\\cdot d\\mathbf{S}\\) للحقل \\(\\langle x, y, z \\rangle\\) عبر نصف الكرة العلوي المفتوح (دون قرص القاعدة \\(z = 0\\)). أي خطوة غير صحيحة؟",steps:["Compute \\(\\operatorname{div}\\mathbf{F} = 1 + 1 + 1 = 3\\).","Equate the open-hemisphere flux directly to \\(\\iiint_E 3\\,dV\\) over the solid hemisphere \\(E\\) without accounting for the missing bottom disk \\(z = 0\\).","Evaluate \\(3 \\cdot \\tfrac{2}{3}\\pi(1)^3 = 2\\pi\\).","Note that on \\(z = 0\\), outward normal is \\(\\langle 0,0,-1\\rangle\\) and \\(\\mathbf{F}\\cdot\\mathbf{n} = -z = 0\\), wait — had \\(\\mathbf{F}\\) had \\(z+1\\), omitting the cap fails!"],steps_ar:["حساب التباعد \\(\\operatorname{div}\\mathbf{F} = 3\\).","مساواة تدفق السطح المفتوح مباشرة بالتكامل الحجمي \\(\\iiint_E 3\\,dV\\) دون إغلاق السطح بقرص القاعدة وحساب تدفقه.","حساب \\(3 \\cdot \\tfrac{2}{3}\\pi = 2\\pi\\).","إغفال شرط أن مبرهنة التباعد تطبق حصراً على الأسطح المغلقة \\(\\partial E\\)."],errorStep:2,reasons:["Gauss’s Divergence Theorem requires a CLOSED boundary surface \\(\\partial E = S \\cup S_{\\text{disk}}\\); for an open surface \\(S\\), you must subtract the flux across the closing cap \\(S_{\\text{disk}}\\).","\\(\\operatorname{div}\\langle x, y, z \\rangle\\) equals \\(x + y + z\\), not \\(3\\).","Stokes’ Theorem computes volume integrals."],reasons_ar:["تتطلب مبرهنة التباعد لغوس سطحاً مغلقاً بالكامل \\(\\partial E = S \\cup S_{\\text{disk}}\\)؛ للسطح المفتوح يجب طرح تدفق غطاء الإغلاق.","تباعد \\(\\langle x, y, z \\rangle\\) يساوي \\(x + y + z\\).","مبرهنة ستوكس تحسب التكاملات الحجمية."],correctReason:0},{t:"ms",ti:"Examiner Mode: Gradient Vector & Hessian Classification (Surface Integrals, the Divergence Theorem & Stokes' Theorem)",ti_ar:"وضع المصحح: متجه التدرج ومصفوفة هيس (التكاملات السطحية ونظرية التباعد (غاوس) ونظرية ستوكس)",q:"Let \\(f(x, y) = 2x^2 + 3xy + y^2\\). (a) Compute \\(\\nabla f(1, 2)\\). (b) Compute the Hessian determinant \\(D = f_{xx}f_{yy} - (f_{xy})^2\\).",q_ar:"لتكن \\(f(x, y) = 2x^2 + 3xy + y^2\\). (أ) احسب متجه التدرج \\(\\nabla f(1, 2)\\). (ب) احسب محدد هيس \\(D = f_{xx}f_{yy} - (f_{xy})^2\\).",parts:[{label:"Part (a) — Partial Derivatives & Gradient",marks:2,rubric:[{code:"M1",marks:1,text:"\\(f_x = 4x + 3y,\\quad f_y = 3x + 2y\\)."},{code:"A1",marks:1,text:"At \\((1, 2)\\): \\(\\nabla f(1, 2) = \\langle 10, 7 \\rangle\\)."}]},{label:"Part (b) — Second-Derivative Discriminant",marks:2,rubric:[{code:"M1",marks:1,text:"\\(f_{xx} = 4,\\; f_{yy} = 2,\\; f_{xy} = 3\\)."},{code:"A1",marks:1,text:"\\(D = (4)(2) - 3^2 = -1\\)."}]}],parts_ar:[{label:"الجزء (أ) — المشتقات الجزئية ومتجه التدرج",marks:2,rubric:[{code:"M1",marks:1,text:"\\(f_x = 4x + 3y,\\quad f_y = 3x + 2y\\)."},{code:"A1",marks:1,text:"عند \\((1, 2)\\): \\(\\nabla f(1, 2) = \\langle 10, 7 \\rangle\\)."}]},{label:"الجزء (ب) — محدد المشتقات الجزئية الثانية (هيس)",marks:2,rubric:[{code:"M1",marks:1,text:"\\(f_{xx} = 4,\\; f_{yy} = 2,\\; f_{xy} = 3\\)."},{code:"A1",marks:1,text:"\\(D = -1\\)."}]}]},{t:"qc",ti:"Quick Check: Stokes’ Theorem vs. Gauss’s Divergence Theorem",ti_ar:"فحص سريع: التمييز بين مبرهنة ستوكس ومبرهنة التباعد",q:"Which vector operator appears inside the surface integral in Stokes’ Theorem \\(\\oint_{\\partial S} \\mathbf{F}\\cdot d\\mathbf{r} = \\iint_S (\\,\\text{?}\\,)\\cdot d\\mathbf{S}\\)?",q_ar:"أي مؤثر متجهي يظهر داخل التكامل السطحي في مبرهنة ستوكس \\(\\oint_{\\partial S} \\mathbf{F}\\cdot d\\mathbf{r} = \\iint_S (\\,\\text{?}\\,)\\cdot d\\mathbf{S}\\)؟",o:["Curl \\(\\nabla \\times \\mathbf{F}\\)","Divergence \\(\\nabla \\cdot \\mathbf{F}\\)","Gradient \\(\\nabla f\\)","Laplacian \\(\\nabla^2 \\mathbf{F}\\)"],o_ar:["الدوران \\(\\nabla \\times \\mathbf{F}\\)","التباعد \\(\\nabla \\cdot \\mathbf{F}\\)","التدرج \\(\\nabla f\\)","مؤثر لابلاس \\(\\nabla^2 \\mathbf{F}\\)"],a:0,ex:"Stokes’ Theorem equates boundary circulation \\(\\oint_{\\partial S} \\mathbf{F}\\cdot d\\mathbf{r}\\) to the surface flux of curl \\(\\iint_S (\\nabla \\times \\mathbf{F})\\cdot d\\mathbf{S}\\).",ex_ar:"تربط مبرهنة ستوكس الدوران الخطي حول حافة السطح بتدفق متجه الدوران \\(\\nabla \\times \\mathbf{F}\\) عبر السطح."}]});